INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,'',1,N'DrugDenominatorKfa',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    1 AS denom,' + CHAR(13) + CHAR(10) + N'    asrib.BridgingID' + CHAR(13) + CHAR(10) + N'FROM TransPrescription AS tp' + CHAR(13) + CHAR(10) + N'INNER JOIN TransPrescriptionItem AS tpi' + CHAR(13) + CHAR(10) + N'    ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'LEFT JOIN AppStandardReferenceItemBridging AS asrib' + CHAR(13) + CHAR(10) + N'    ON tpi.SRItemUnit = asrib.ItemID' + CHAR(13) + CHAR(10) + N'   AND asrib.StandardReferenceID = ''ItemUnit''' + CHAR(13) + CHAR(10) + N'   AND asrib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'WHERE tp.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'  AND tp.IsVoid = 0' + CHAR(13) + CHAR(10) + N'  AND tpi.IsVoid = 0' + CHAR(13) + CHAR(10) + N'  AND tp.IsApproval = 1' + CHAR(13) + CHAR(10) + N'  AND tpi.IsApprove = 1' + CHAR(13) + CHAR(10) + N'  AND tpi.IsCompound = 0' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,'',1,N'DrugDenominatorSystemKfa',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    asrib.BridgingID,' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN asrib.BridgingID IN (''mg'', ''g'', ''mcg'', ''mL'', ''L'', ''IU'')' + CHAR(13) + CHAR(10) + N'        THEN ''http://unitsofmeasure.org''' + CHAR(13) + CHAR(10) + N'        ELSE ''http://terminology.hl7.org/CodeSystem/v3-orderableDrugForm''' + CHAR(13) + CHAR(10) + N'    END AS denominator_system' + CHAR(13) + CHAR(10) + N'FROM TransPrescription AS tp' + CHAR(13) + CHAR(10) + N'INNER JOIN TransPrescriptionItem AS tpi' + CHAR(13) + CHAR(10) + N'    ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'LEFT JOIN AppStandardReferenceItemBridging AS asrib' + CHAR(13) + CHAR(10) + N'    ON tpi.SRItemUnit = asrib.ItemID' + CHAR(13) + CHAR(10) + N'   AND asrib.StandardReferenceID = ''ItemUnit''' + CHAR(13) + CHAR(10) + N'   AND asrib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'WHERE tp.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'  AND tp.IsVoid = 0' + CHAR(13) + CHAR(10) + N'  AND tpi.IsVoid = 0' + CHAR(13) + CHAR(10) + N'  AND tp.IsApproval = 1' + CHAR(13) + CHAR(10) + N'  AND tpi.IsApprove = 1' + CHAR(13) + CHAR(10) + N'  AND tpi.IsCompound = 0' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,'',1,N'Patient_Class',0,N'sql',N'SELECT TOP 1      COALESCE(cb.BridgingID, ''1'') AS BridgingID,      COALESCE(cb.BridgingName, ''Kelas 1'') AS BridgingName  ' + CHAR(13) + CHAR(10) + CHAR(9) + N'          FROM Registration r  OUTER APPLY (      SELECT TOP 1 BridgingID, BridgingName      FROM ClassBridging cb      ' + CHAR(13) + CHAR(10) + CHAR(9) + N'          WHERE cb.ClassID = r.ClassID        AND cb.IsActive = 1 AND cb.SRBridgingType = ''{{SatuSehatBridgingTypeID}}'' ) cb  WHERE r.RegistrationNo = ''@RegistrationNo''  ',0);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,'',1,N'ServiceUnitRadiologyID',0,N'sql',N'SELECT DISTINCT ServiceUnitID' + CHAR(13) + CHAR(10) + N'FROM (' + CHAR(13) + CHAR(10) + N'    SELECT LTRIM(RTRIM(' + CHAR(13) + CHAR(10) + N'             SUBSTRING(' + CHAR(13) + CHAR(10) + N'               ap.ParameterValue,' + CHAR(13) + CHAR(10) + N'               s.number,' + CHAR(13) + CHAR(10) + N'               NULLIF(CHARINDEX('','', ap.ParameterValue + '','', s.number) - s.number, -1)' + CHAR(13) + CHAR(10) + N'             )' + CHAR(13) + CHAR(10) + N'           )) AS ServiceUnitID' + CHAR(13) + CHAR(10) + N'    FROM AppParameter ap' + CHAR(13) + CHAR(10) + N'    JOIN master.dbo.spt_values s' + CHAR(13) + CHAR(10) + N'      ON s.type = ''P''' + CHAR(13) + CHAR(10) + N'     AND s.number BETWEEN 1 AND LEN(ISNULL(ap.ParameterValue, ''''))' + CHAR(13) + CHAR(10) + N'    WHERE ap.ParameterID = ''ServiceUnitRadiologyIdArray''' + CHAR(13) + CHAR(10) + N'      AND ISNULL(ap.ParameterValue, '''') <> ''''' + CHAR(13) + CHAR(10) + N'      AND SUBSTRING('','' + ap.ParameterValue, s.number, 1) = '',''' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + N'    UNION ALL' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + N'    SELECT LTRIM(RTRIM(ap.ParameterValue)) AS ServiceUnitID' + CHAR(13) + CHAR(10) + N'    FROM AppParameter ap' + CHAR(13) + CHAR(10) + N'    WHERE ap.ParameterID = ''ServiceUnitRadiologyID''' + CHAR(13) + CHAR(10) + N') x',1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'AdlScore',1,N'sql',N'SELECT phrl.QuestionAnswerText' + CHAR(13) + CHAR(10) + N'FROM AppParameter ap' + CHAR(13) + CHAR(10) + N'CROSS APPLY (' + CHAR(13) + CHAR(10) + N'    SELECT ' + CHAR(13) + CHAR(10) + N'        CASE ' + CHAR(13) + CHAR(10) + N'            WHEN CHARINDEX(''|'', ap.parametervalue) > 0' + CHAR(13) + CHAR(10) + N'            THEN LEFT(ap.parametervalue, CHARINDEX(''|'', ap.parametervalue) - 1)' + CHAR(13) + CHAR(10) + N'            ELSE ap.parametervalue' + CHAR(13) + CHAR(10) + N'        END AS QuestionFormID,' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + N'        CASE ' + CHAR(13) + CHAR(10) + N'            WHEN CHARINDEX(''|'', ap.parametervalue) > 0' + CHAR(13) + CHAR(10) + N'            THEN SUBSTRING(ap.parametervalue, CHARINDEX(''|'', ap.parametervalue) + 1, LEN(ap.parametervalue))' + CHAR(13) + CHAR(10) + N'            ELSE NULL' + CHAR(13) + CHAR(10) + N'        END AS QuestionID' + CHAR(13) + CHAR(10) + N') AS q' + CHAR(13) + CHAR(10) + N'JOIN PatientHealthRecordLine phrl' + CHAR(13) + CHAR(10) + N'    ON phrl.QuestionFormID = q.QuestionFormID' + CHAR(13) + CHAR(10) + N'   AND phrl.QuestionID = q.QuestionID' + CHAR(13) + CHAR(10) + N'WHERE ap.ParameterID = ''AdlScoreQuestionFormIdAndQuestionId''' + CHAR(13) + CHAR(10) + N'  AND phrl.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10),NULL);
