INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'DosageForm',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    x.dosage_form_code,' + CHAR(13) + CHAR(10) + N'    x.dosage_form_name' + CHAR(13) + CHAR(10) + N'FROM (' + CHAR(13) + CHAR(10) + N'    SELECT ' + CHAR(13) + CHAR(10) + N'        tp.RegistrationNo,' + CHAR(13) + CHAR(10) + N'        JSON_VALUE(' + CHAR(13) + CHAR(10) + N'            CASE ' + CHAR(13) + CHAR(10) + N'                WHEN tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = ''''' + CHAR(13) + CHAR(10) + N'                    THEN ssk1.ss_result' + CHAR(13) + CHAR(10) + N'                ELSE ssk2.ss_result' + CHAR(13) + CHAR(10) + N'            END,' + CHAR(13) + CHAR(10) + N'            ''$.data.dosage_form.code''' + CHAR(13) + CHAR(10) + N'        ) AS dosage_form_code,' + CHAR(13) + CHAR(10) + N'        JSON_VALUE(' + CHAR(13) + CHAR(10) + N'            CASE ' + CHAR(13) + CHAR(10) + N'                WHEN tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = ''''' + CHAR(13) + CHAR(10) + N'                    THEN ssk1.ss_result' + CHAR(13) + CHAR(10) + N'                ELSE ssk2.ss_result' + CHAR(13) + CHAR(10) + N'            END,' + CHAR(13) + CHAR(10) + N'            ''$.data.dosage_form.name''' + CHAR(13) + CHAR(10) + N'        ) AS dosage_form_name,' + CHAR(13) + CHAR(10) + N'        tpi.ItemID AS item,' + CHAR(13) + CHAR(10) + N'        tpi.CreatedDateTime' + CHAR(13) + CHAR(10) + N'    FROM TransPrescription AS tp' + CHAR(13) + CHAR(10) + N'    INNER JOIN TransPrescriptionItem AS tpi' + CHAR(13) + CHAR(10) + N'        ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'    LEFT JOIN ItemBridging AS ib1' + CHAR(13) + CHAR(10) + N'        ON ib1.ItemID = tpi.ItemID AND ib1.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'        AND (tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = '''')' + CHAR(13) + CHAR(10) + N'    LEFT JOIN ItemBridging AS ib2' + CHAR(13) + CHAR(10) + N'        ON ib2.ItemID = tpi.ItemInterventionID AND ib2.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'        AND (tpi.ItemInterventionID IS NOT NULL AND tpi.ItemInterventionID <> '''')' + CHAR(13) + CHAR(10) + N'    LEFT JOIN SatuSehatKfa AS ssk1' + CHAR(13) + CHAR(10) + N'        ON ssk1.ss_uuid = ib1.BridgingID' + CHAR(13) + CHAR(10) + N'        AND (tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = '''')' + CHAR(13) + CHAR(10) + N'    LEFT JOIN SatuSehatKfa AS ssk2' + CHAR(13) + CHAR(10) + N'        ON ssk2.ss_uuid = ib2.BridgingID' + CHAR(13) + CHAR(10) + N'        AND (tpi.ItemInterventionID IS NOT NULL AND tpi.ItemInterventionID <> '''')' + CHAR(13) + CHAR(10) + N'    WHERE ' + CHAR(13) + CHAR(10) + N'        tp.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'        AND tp.IsVoid = 0' + CHAR(13) + CHAR(10) + N'        AND tpi.IsVoid = 0' + CHAR(13) + CHAR(10) + N'        AND tp.IsApproval = 1' + CHAR(13) + CHAR(10) + N'        AND tpi.IsApprove = 1' + CHAR(13) + CHAR(10) + N'        AND tpi.IsCompound = 0' + CHAR(13) + CHAR(10) + N') AS x' + CHAR(13) + CHAR(10) + N'ORDER BY ' + CHAR(13) + CHAR(10) + N'    x.CreatedDateTime' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'DosageFormHome',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    x.dosage_form_code,' + CHAR(13) + CHAR(10) + N'    x.dosage_form_name' + CHAR(13) + CHAR(10) + N'FROM (' + CHAR(13) + CHAR(10) + N'    SELECT ' + CHAR(13) + CHAR(10) + N'        mr.RegistrationNo,' + CHAR(13) + CHAR(10) + N'        JSON_VALUE(ssk.ss_result, ''$.data.dosage_form.code'') AS dosage_form_code,' + CHAR(13) + CHAR(10) + N'        JSON_VALUE(ssk.ss_result, ''$.data.dosage_form.name'') AS dosage_form_name' + CHAR(13) + CHAR(10) + N'    FROM MedicationReceive AS mr' + CHAR(13) + CHAR(10) + N'    INNER JOIN TransPrescriptionItem AS tpi' + CHAR(13) + CHAR(10) + N'        ON mr.RefTransactionNo = tpi.PrescriptionNo' + CHAR(13) + CHAR(10) + N'    LEFT JOIN ItemBridging AS ib' + CHAR(13) + CHAR(10) + N'        ON ib.ItemID = mr.ItemID AND ib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'    LEFT JOIN SatuSehatKfa AS ssk' + CHAR(13) + CHAR(10) + N'        ON ssk.ss_uuid = ib.BridgingID' + CHAR(13) + CHAR(10) + N'    WHERE ' + CHAR(13) + CHAR(10) + N'        mr.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'        AND mr.IsVoid = 0' + CHAR(13) + CHAR(10) + N'        AND mr.IsBroughtHome = 1' + CHAR(13) + CHAR(10) + N'        AND tpi.IsCompound = 0' + CHAR(13) + CHAR(10) + N'        AND tpi.ItemID = mr.ItemID' + CHAR(13) + CHAR(10) + N') AS x' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'DrugAllergyClinical',0,N'sql',N'SELECT' + CHAR(13) + CHAR(10) + N'    LOWER(' + CHAR(13) + CHAR(10) + N'        CASE ' + CHAR(13) + CHAR(10) + N'            WHEN SRAllergyClinicalStatus IS NULL OR LTRIM(RTRIM(SRAllergyClinicalStatus)) = ''''' + CHAR(13) + CHAR(10) + N'            THEN ''active''' + CHAR(13) + CHAR(10) + N'            ELSE SRAllergyClinicalStatus' + CHAR(13) + CHAR(10) + N'        END' + CHAR(13) + CHAR(10) + N'    ) AS verificationstatus_lower,' + CHAR(13) + CHAR(10) + N'    ' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN SRAllergyClinicalStatus IS NULL OR LTRIM(RTRIM(SRAllergyClinicalStatus)) = ''''' + CHAR(13) + CHAR(10) + N'        THEN ''active''' + CHAR(13) + CHAR(10) + N'        ELSE SRAllergyClinicalStatus' + CHAR(13) + CHAR(10) + N'    END AS VerificationStatus' + CHAR(13) + CHAR(10) + N'FROM ' + CHAR(13) + CHAR(10) + N'    PatientAllergy pa' + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    pa.SRAllergyCategory = ''Medication''' + CHAR(13) + CHAR(10) + N'    AND pa.PatientID = ''{{PatientID_HIS}}''',1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'DrugAllergyDescAndReaction',0,N'sql',N'SELECT pa.DescAndReaction FROM PatientAllergy AS pa WHERE pa.SRAllergyCategory = ''Medication'' and pa.PatientID = ''{{PatientID_HIS}}''',1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'DrugAllergyVerification',0,N'sql',N'SELECT' + CHAR(13) + CHAR(10) + N'    LOWER(' + CHAR(13) + CHAR(10) + N'        CASE' + CHAR(13) + CHAR(10) + N'            WHEN SRAllergyVerificationStatus IS NULL OR LTRIM(RTRIM(SRAllergyVerificationStatus)) = ''''' + CHAR(13) + CHAR(10) + N'            THEN ''confirmed''' + CHAR(13) + CHAR(10) + N'            ELSE SRAllergyVerificationStatus' + CHAR(13) + CHAR(10) + N'        END' + CHAR(13) + CHAR(10) + N'    ) AS verificationstatus_lower,' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + N'    CASE' + CHAR(13) + CHAR(10) + N'        WHEN SRAllergyVerificationStatus IS NULL OR LTRIM(RTRIM(SRAllergyVerificationStatus)) = ''''' + CHAR(13) + CHAR(10) + N'        THEN ''confirmed''' + CHAR(13) + CHAR(10) + N'        ELSE SRAllergyVerificationStatus' + CHAR(13) + CHAR(10) + N'    END AS VerificationStatus' + CHAR(13) + CHAR(10) + N'FROM' + CHAR(13) + CHAR(10) + N'    PatientAllergy pa' + CHAR(13) + CHAR(10) + N'WHERE' + CHAR(13) + CHAR(10) + N'    pa.SRAllergyCategory = ''Medication''' + CHAR(13) + CHAR(10) + N'    AND pa.PatientID = ''{{PatientID_HIS}}''' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'DrugExpirationDate',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    CASE' + CHAR(13) + CHAR(10) + N'        WHEN im.ExpiredDate IS NULL ' + CHAR(13) + CHAR(10) + N'             OR LTRIM(RTRIM(CONVERT(VARCHAR, im.ExpiredDate, 120))) = ''''' + CHAR(13) + CHAR(10) + N'        THEN CONVERT(DATE, DATEADD(DAY, 60, GETDATE()))' + CHAR(13) + CHAR(10) + N'        ELSE CONVERT(DATE, im.ExpiredDate)' + CHAR(13) + CHAR(10) + N'    END AS ExpiredDate' + CHAR(13) + CHAR(10) + N'FROM TransPrescription AS tp' + CHAR(13) + CHAR(10) + N'INNER JOIN TransPrescriptionItem AS tpi ' + CHAR(13) + CHAR(10) + N'    ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'INNER JOIN ItemMovement AS im ' + CHAR(13) + CHAR(10) + N'    ON im.TransactionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'   AND im.SequenceNo = tpi.SequenceNo' + CHAR(13) + CHAR(10) + N'   AND im.TransactionCode = ''091''' + CHAR(13) + CHAR(10) + N'WHERE tp.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'  AND tp.IsVoid = 0' + CHAR(13) + CHAR(10) + N'  AND tpi.IsVoid = 0' + CHAR(13) + CHAR(10) + N'  AND tp.IsApproval = 1' + CHAR(13) + CHAR(10) + N'  AND tpi.IsApprove = 1' + CHAR(13) + CHAR(10) + N'  AND tpi.IsCompound = 0' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'DrugIterationQty',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    ISNULL(cm.IterationQty, 1) AS IterationQty' + CHAR(13) + CHAR(10) + N'FROM TransPrescription AS tp' + CHAR(13) + CHAR(10) + N'INNER JOIN TransPrescriptionItem AS tpi' + CHAR(13) + CHAR(10) + N'    ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'INNER JOIN ConsumeMethod AS cm' + CHAR(13) + CHAR(10) + N'    ON cm.SRConsumeMethod = tpi.SRConsumeMethod' + CHAR(13) + CHAR(10) + N'WHERE tp.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'  AND tp.IsVoid = 0' + CHAR(13) + CHAR(10) + N'  AND tpi.IsVoid = 0' + CHAR(13) + CHAR(10) + N'  AND tp.IsApproval = 1' + CHAR(13) + CHAR(10) + N'  AND tpi.IsApprove = 1' + CHAR(13) + CHAR(10) + N'  AND tpi.IsCompound = 0',1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'DrugIterationQtyHome',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    cm.IterationQty' + CHAR(13) + CHAR(10) + N'FROM MedicationReceive AS mr' + CHAR(13) + CHAR(10) + N'INNER JOIN TransPrescriptionItem AS tpi ' + CHAR(13) + CHAR(10) + N'    ON mr.RefTransactionNo = tpi.PrescriptionNo' + CHAR(13) + CHAR(10) + N'INNER JOIN ConsumeMethod AS cm' + CHAR(13) + CHAR(10) + N'    ON cm.SRConsumeMethod = mr.SRConsumeMethod' + CHAR(13) + CHAR(10) + N'WHERE mr.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'  AND mr.IsVoid = 0' + CHAR(13) + CHAR(10) + N'  AND mr.IsBroughtHome = 1' + CHAR(13) + CHAR(10) + N'  AND tpi.IsCompound = 0' + CHAR(13) + CHAR(10) + N'  AND tpi.ItemID = mr.ItemID' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'DruglotNumber',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    CASE' + CHAR(13) + CHAR(10) + N'        WHEN im.BatchNumber IS NULL ' + CHAR(13) + CHAR(10) + N'             OR LTRIM(RTRIM(im.BatchNumber)) = ''''' + CHAR(13) + CHAR(10) + N'        THEN ''-''' + CHAR(13) + CHAR(10) + N'        ELSE im.BatchNumber' + CHAR(13) + CHAR(10) + N'    END AS BatchNumber' + CHAR(13) + CHAR(10) + N'FROM TransPrescription AS tp' + CHAR(13) + CHAR(10) + N'INNER JOIN TransPrescriptionItem AS tpi ' + CHAR(13) + CHAR(10) + N'    ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'INNER JOIN ItemMovement AS im ' + CHAR(13) + CHAR(10) + N'    ON im.TransactionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'   AND im.SequenceNo = tpi.SequenceNo' + CHAR(13) + CHAR(10) + N'   AND im.TransactionCode = ''091''' + CHAR(13) + CHAR(10) + N'WHERE tp.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'  AND tp.IsVoid = 0' + CHAR(13) + CHAR(10) + N'  AND tpi.IsVoid = 0' + CHAR(13) + CHAR(10) + N'  AND tp.IsApproval = 1' + CHAR(13) + CHAR(10) + N'  AND tpi.IsApprove = 1' + CHAR(13) + CHAR(10) + N'  AND tpi.IsCompound = 0' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'DrugNumeratorKfa',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN CHARINDEX('' '', ai.kekuatan_zat_aktif + '' '') > 1 ' + CHAR(13) + CHAR(10) + N'            THEN LEFT(ai.kekuatan_zat_aktif, CHARINDEX('' '', ai.kekuatan_zat_aktif + '' '') - 1)' + CHAR(13) + CHAR(10) + N'        ELSE ai.kekuatan_zat_aktif' + CHAR(13) + CHAR(10) + N'    END AS kekuatan_value,' + CHAR(13) + CHAR(10) + N'    ' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN CHARINDEX('' '', ai.kekuatan_zat_aktif + '' '') < LEN(ai.kekuatan_zat_aktif) + 1' + CHAR(13) + CHAR(10) + N'            THEN LTRIM(' + CHAR(13) + CHAR(10) + N'                RIGHT(' + CHAR(13) + CHAR(10) + N'                    ai.kekuatan_zat_aktif,' + CHAR(13) + CHAR(10) + N'                    LEN(ai.kekuatan_zat_aktif) - CHARINDEX('' '', ai.kekuatan_zat_aktif + '' '')' + CHAR(13) + CHAR(10) + N'                )' + CHAR(13) + CHAR(10) + N'            )' + CHAR(13) + CHAR(10) + N'        ELSE NULL' + CHAR(13) + CHAR(10) + N'    END AS kekuatan_unit,' + CHAR(13) + CHAR(10) + N'    ' + CHAR(13) + CHAR(10) + N'    tpi.PrescriptionNo + ''-'' + CAST(tpi.SequenceNo AS VARCHAR) AS TransSeq' + CHAR(13) + CHAR(10) + N'FROM TransPrescription AS tp' + CHAR(13) + CHAR(10) + N'INNER JOIN TransPrescriptionItem AS tpi' + CHAR(13) + CHAR(10) + N'    ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemBridging AS ib1' + CHAR(13) + CHAR(10) + N'    ON ib1.ItemID = tpi.ItemID AND ib1.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = '''')' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemBridging AS ib2' + CHAR(13) + CHAR(10) + N'    ON ib2.ItemID = tpi.ItemInterventionID AND ib2.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NOT NULL AND tpi.ItemInterventionID <> '''')' + CHAR(13) + CHAR(10) + N'LEFT JOIN SatuSehatKfa AS ssk1' + CHAR(13) + CHAR(10) + N'    ON ssk1.ss_uuid = ib1.BridgingID' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = '''')' + CHAR(13) + CHAR(10) + N'LEFT JOIN SatuSehatKfa AS ssk2' + CHAR(13) + CHAR(10) + N'    ON ssk2.ss_uuid = ib2.BridgingID' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NOT NULL AND tpi.ItemInterventionID <> '''')' + CHAR(13) + CHAR(10) + N'OUTER APPLY OPENJSON(' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = ''''' + CHAR(13) + CHAR(10) + N'            THEN ssk1.ss_result' + CHAR(13) + CHAR(10) + N'        ELSE ssk2.ss_result' + CHAR(13) + CHAR(10) + N'    END,' + CHAR(13) + CHAR(10) + N'    ''$.data.active_ingredients''' + CHAR(13) + CHAR(10) + N')' + CHAR(13) + CHAR(10) + N'WITH (' + CHAR(13) + CHAR(10) + N'    zat_aktif           NVARCHAR(200) ''$.zat_aktif'',' + CHAR(13) + CHAR(10) + N'    kekuatan_zat_aktif  NVARCHAR(200) ''$.kekuatan_zat_aktif'',' + CHAR(13) + CHAR(10) + N'    kfa_code            VARCHAR(20)   ''$.kfa_code''' + CHAR(13) + CHAR(10) + N') AS ai' + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    tp.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'    AND tp.IsVoid = 0' + CHAR(13) + CHAR(10) + N'    AND tpi.IsVoid = 0' + CHAR(13) + CHAR(10) + N'    AND tp.IsApproval = 1' + CHAR(13) + CHAR(10) + N'    AND tpi.IsApprove = 1' + CHAR(13) + CHAR(10) + N'    AND tpi.IsCompound = 0' + CHAR(13) + CHAR(10) + N'ORDER BY ' + CHAR(13) + CHAR(10) + N'    tpi.CreatedDateTime' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'DrugNumeratorKfaHome',0,N'sql',N'SELECT' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN x.kekuatan_zat_aktif IS NOT NULL' + CHAR(13) + CHAR(10) + N'             AND LEN(x.kekuatan_zat_aktif) > 0' + CHAR(13) + CHAR(10) + N'             AND CHARINDEX('' '', x.kekuatan_zat_aktif + '' '') > 1' + CHAR(13) + CHAR(10) + N'            THEN LEFT(x.kekuatan_zat_aktif, CHARINDEX('' '', x.kekuatan_zat_aktif + '' '') - 1)' + CHAR(13) + CHAR(10) + N'        ELSE x.kekuatan_zat_aktif' + CHAR(13) + CHAR(10) + N'    END AS kekuatan_value,' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN x.kekuatan_zat_aktif IS NOT NULL' + CHAR(13) + CHAR(10) + N'             AND LEN(x.kekuatan_zat_aktif) > 0' + CHAR(13) + CHAR(10) + N'             AND CHARINDEX('' '', x.kekuatan_zat_aktif + '' '') < LEN(x.kekuatan_zat_aktif) + 1' + CHAR(13) + CHAR(10) + N'            THEN LTRIM(' + CHAR(13) + CHAR(10) + N'                RIGHT(' + CHAR(13) + CHAR(10) + N'                    x.kekuatan_zat_aktif,' + CHAR(13) + CHAR(10) + N'                    LEN(x.kekuatan_zat_aktif) - CHARINDEX('' '', x.kekuatan_zat_aktif + '' '')' + CHAR(13) + CHAR(10) + N'                )' + CHAR(13) + CHAR(10) + N'            )' + CHAR(13) + CHAR(10) + N'        ELSE NULL' + CHAR(13) + CHAR(10) + N'    END AS kekuatan_unit' + CHAR(13) + CHAR(10) + N'FROM (' + CHAR(13) + CHAR(10) + N'    SELECT' + CHAR(13) + CHAR(10) + N'        mr.RegistrationNo,' + CHAR(13) + CHAR(10) + N'        JSON_VALUE(' + CHAR(13) + CHAR(10) + N'            ssk.ss_result,' + CHAR(13) + CHAR(10) + N'            ''$.data.active_ingredients[0].kekuatan_zat_aktif''' + CHAR(13) + CHAR(10) + N'        ) AS kekuatan_zat_aktif' + CHAR(13) + CHAR(10) + N'    FROM MedicationReceive AS mr' + CHAR(13) + CHAR(10) + N'    INNER JOIN TransPrescriptionItem AS tpi' + CHAR(13) + CHAR(10) + N'        ON tpi.PrescriptionNo = mr.RefTransactionNo' + CHAR(13) + CHAR(10) + N'    LEFT JOIN ItemBridging AS ib' + CHAR(13) + CHAR(10) + N'        ON ib.ItemID = mr.ItemID AND ib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'    LEFT JOIN SatuSehatKfa AS ssk' + CHAR(13) + CHAR(10) + N'        ON ssk.ss_uuid = ib.BridgingID' + CHAR(13) + CHAR(10) + N'    WHERE' + CHAR(13) + CHAR(10) + N'        mr.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'        AND mr.IsVoid = 0' + CHAR(13) + CHAR(10) + N'        AND mr.IsBroughtHome = 1' + CHAR(13) + CHAR(10) + N'        AND tpi.IsCompound = 0' + CHAR(13) + CHAR(10) + N'        AND tpi.ItemID = mr.ItemID' + CHAR(13) + CHAR(10) + N') AS x' + CHAR(13) + CHAR(10),1);
