VALUES(0,N'-',1,N'FastingStatus',1,N'sql',N'SELECT TOP 1         CASE               WHEN ISNULL(il.IsFasting, 0) = 1                    THEN ''completed''               ELSE ''not-done''          END AS Status,         CASE               WHEN ISNULL(il.IsFasting, 0) = 1                    THEN ''Prosedur Puasa dilakukan Pasien''              ELSE ''Prosedur Puasa tidak dilakukan Pasien''         END AS Keterangan  FROM   TransCharges AS tc         INNER JOIN TransChargesItem AS parent                  ON parent.TransactionNo = tc.TransactionNo         LEFT JOIN ItemLaboratory AS il                 ON il.ItemID = parent.ItemID  WHERE  tc.RegistrationNo   = ''@RegistrationNo''         AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'')         AND (parent.ParentNo IS NULL OR LTRIM(RTRIM(parent.ParentNo)) = '''')         AND parent.IsOrderRealization = 1         AND parent.IsVoid = 0         AND parent.IsApprove = 1   ',1);
