VALUES(0,N'-',1,N'IsPregnant',1,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN ISNULL(r.IsPregnant, 0) = 1 ' + CHAR(13) + CHAR(10) + N'            THEN ''77386006'' ' + CHAR(13) + CHAR(10) + N'        ELSE ''60001007'' ' + CHAR(13) + CHAR(10) + N'    END AS code,' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN ISNULL(r.IsPregnant, 0) = 1 ' + CHAR(13) + CHAR(10) + N'            THEN ''Pregnancy''' + CHAR(13) + CHAR(10) + N'        ELSE ''Not pregnant''' + CHAR(13) + CHAR(10) + N'    END AS name' + CHAR(13) + CHAR(10) + N'FROM Registration AS r' + CHAR(13) + CHAR(10) + N'WHERE r.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10),1);
