VALUES(0,N'-',1,N'LaboratoryProcedure_NotesSingleItem',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    tci.Notes' + CHAR(13) + CHAR(10) + N'FROM TransCharges AS tc' + CHAR(13) + CHAR(10) + N'INNER JOIN TransChargesItem AS tci' + CHAR(13) + CHAR(10) + N'    ON tci.TransactionNo = tc.TransactionNo' + CHAR(13) + CHAR(10) + N'INNER JOIN ItemBridging AS ib' + CHAR(13) + CHAR(10) + N'    ON ib.ItemID = tci.ItemID' + CHAR(13) + CHAR(10) + N'WHERE tc.RegistrationNo      = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'  AND tc.ToServiceUnitID     IN (''{{ServiceUnitLaboratoryID}}'')' + CHAR(13) + CHAR(10) + N'  AND tci.IsOrderRealization = 1' + CHAR(13) + CHAR(10) + N'  AND tci.IsVoid             = 0' + CHAR(13) + CHAR(10) + N'  AND tci.SRCollectMethod IS NOT NULL' + CHAR(13) + CHAR(10) + N'  AND LTRIM(RTRIM(tci.SRCollectMethod)) <> ''''' + CHAR(13) + CHAR(10) + N'  AND tc.IsOrder             = 1' + CHAR(13) + CHAR(10) + N'  AND tc.IsApproved          = 1' + CHAR(13) + CHAR(10) + N'  AND ib.SRBridgingType      = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'  AND (tci.ParentNo IS NULL OR LTRIM(RTRIM(tci.ParentNo)) = '''') ' + CHAR(13) + CHAR(10) + N'  AND NOT EXISTS (                                             ' + CHAR(13) + CHAR(10) + N'        SELECT 1' + CHAR(13) + CHAR(10) + N'        FROM TransChargesItem AS child' + CHAR(13) + CHAR(10) + N'        WHERE child.TransactionNo = tci.TransactionNo' + CHAR(13) + CHAR(10) + N'          AND child.ParentNo      = tci.SequenceNo' + CHAR(13) + CHAR(10) + N'    )' + CHAR(13) + CHAR(10),1);
