VALUES(0,N'-',1,N'LaboratoryTestValue',1,N'sql',N'SELECT tci.ResultValue FROM TransCharges AS tc INNER JOIN TransChargesItem AS tci ON tci.TransactionNo = tc.TransactionNo WHERE tc.RegistrationNo = ''@RegistrationNo'' AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'') AND tci.IsOrderRealization = 1 AND tci.IsVoid = 0 AND tc.IsOrder = 1 AND tc.IsApproved = 1' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'LabTestInterpretation',0,N'sql',N'SELECT' + CHAR(13) + CHAR(10) + N'    CASE' + CHAR(13) + CHAR(10) + N'        WHEN r.val < d.NormalValueMin THEN ''L''' + CHAR(13) + CHAR(10) + N'        WHEN r.val > d.NormalValueMax THEN ''H''' + CHAR(13) + CHAR(10) + N'        ELSE ''N''' + CHAR(13) + CHAR(10) + N'    END AS Code,' + CHAR(13) + CHAR(10) + N'    CASE' + CHAR(13) + CHAR(10) + N'        WHEN r.val < d.NormalValueMin THEN ''Low''' + CHAR(13) + CHAR(10) + N'        WHEN r.val > d.NormalValueMax THEN ''High''' + CHAR(13) + CHAR(10) + N'        ELSE ''NORMAL''' + CHAR(13) + CHAR(10) + N'    END AS Name' + CHAR(13) + CHAR(10) + N'FROM' + CHAR(13) + CHAR(10) + N'    (' + CHAR(13) + CHAR(10) + N'      SELECT i.ItemID ItemID, tci.ResultValue val FROM TransCharges AS tc INNER JOIN TransChargesItem AS tci ON tci.TransactionNo = tc.TransactionNo INNER JOIN Item AS i ON i.ItemID = tci.ItemID WHERE tc.RegistrationNo = ''@RegistrationNo'' AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'') AND tci.IsOrderRealization = 1 AND tci.IsVoid = 0 AND tc.IsOrder = 1 AND tc.IsApproved = 1  ' + CHAR(13) + CHAR(10) + N'    ) r' + CHAR(13) + CHAR(10) + N'INNER JOIN' + CHAR(13) + CHAR(10) + N'    ItemLaboratoryDetail d ON r.ItemID = d.ItemID' + CHAR(13) + CHAR(10) + N'INNER JOIN ' + CHAR(13) + CHAR(10) + N'    Patient p ON p.Sex = d.Sex' + CHAR(13) + CHAR(10) + N'WHERE' + CHAR(13) + CHAR(10) + N'    p.PatientID = ''{{PatientID_HIS}}''' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'LabTestNormalValueMax',0,N'sql',N'SELECT  ISNULL((          SELECT TOP 1 ild.NormalValueMax          FROM ItemLaboratoryDetail AS ild          WHERE ild.ItemID = tci.ItemID            AND ild.Sex = p.Sex            AND r.AgeInYear BETWEEN ild.AgeMin AND ild.AgeMax      ), CAST(0 AS DECIMAL(18,2))) AS NormalValueMax  FROM       TransCharges AS tc  INNER JOIN       TransChargesItem AS tci ON tci.TransactionNo = tc.TransactionNo  INNER JOIN       Registration AS r ON tc.RegistrationNo = r.RegistrationNo  INNER JOIN       Patient AS p ON p.PatientID = r.PatientID  WHERE       tc.RegistrationNo = ''@RegistrationNo''      AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'')      AND tci.IsOrderRealization = 1       AND tci.IsVoid = 0       AND tc.IsOrder = 1       AND tc.IsApproved = 1      AND tc.IsValidated = 1  ',1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'LabTestNormalValueMin',0,N'sql',N'SELECT       ISNULL((          SELECT TOP 1 ild.NormalValueMin          FROM ItemLaboratoryDetail AS ild          WHERE ild.ItemID = tci.ItemID            AND ild.Sex = p.Sex            AND r.AgeInYear BETWEEN ild.AgeMin AND ild.AgeMax      ), CAST(0 AS DECIMAL(18,2))) AS NormalValueMin  FROM       TransCharges AS tc  INNER JOIN       TransChargesItem AS tci ON tci.TransactionNo = tc.TransactionNo  INNER JOIN       Registration AS r ON tc.RegistrationNo = r.RegistrationNo  INNER JOIN       Patient AS p ON p.PatientID = r.PatientID  WHERE       tc.RegistrationNo = ''@RegistrationNo''      AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'')      AND tci.IsOrderRealization = 1       AND tci.IsVoid = 0       AND tc.IsOrder = 1       AND tc.IsApproved = 1      AND tc.IsValidated = 1  ',1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'LabTransaction_Date',0,N'sql',N'SELECT tc.TransactionDate FROM TransCharges AS tc INNER JOIN TransChargesItem AS tci ON tci.TransactionNo = tc.TransactionNo WHERE tc.RegistrationNo = ''@RegistrationNo'' AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'') AND tci.IsOrderRealization = 1 AND tci.IsVoid = 0 AND tc.IsOrder = 1 AND tc.IsApproved = 1 ' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'LabTransactionNo',0,N'sql',N'SELECT tci.TransactionNo + ''-'' + CAST(tci.SequenceNo AS VARCHAR) AS TransSeq FROM TransCharges AS tc INNER JOIN TransChargesItem AS tci ON tci.TransactionNo = tc.TransactionNo WHERE tc.RegistrationNo = ''@RegistrationNo'' AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'') AND tci.IsOrderRealization = 1 AND tci.IsVoid = 0 AND tc.IsOrder = 1 AND tc.IsApproved = 1   ',1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'LabTransactionNo_Specimen',0,N'sql',N'SELECT tc.TransactionNo FROM TransCharges AS tc INNER JOIN TransChargesItem AS tci ON tci.TransactionNo = tc.TransactionNo WHERE tc.RegistrationNo = ''@RegistrationNo'' AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'') AND tci.IsOrderRealization = 1 AND tci.IsVoid = 0 AND tc.IsOrder = 1 AND tc.IsApproved = 1 AND tci.SRCollectMethod IS NOT NULL AND tci.SRCollectMethod <> ''''',1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'LengthOfStay',0,N'sql',N'SELECT' + CHAR(13) + CHAR(10) + N'    DATEDIFF(DAY, r.RegistrationDate, m.DischargeDate) AS LengthOfStay' + CHAR(13) + CHAR(10) + N'FROM Registration r' + CHAR(13) + CHAR(10) + N'JOIN MedicalDischargeSummary m ' + CHAR(13) + CHAR(10) + N'    ON r.RegistrationNo = m.RegistrationNo' + CHAR(13) + CHAR(10) + N'WHERE m.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10),0);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'LevelOfResponsiveness',1,N'sql',N'SELECT' + CHAR(13) + CHAR(10) + N'  CASE ' + CHAR(13) + CHAR(10) + N'      WHEN val LIKE ''%Composmentis%'' THEN ''248234008''' + CHAR(13) + CHAR(10) + N'      WHEN val LIKE ''%Somnolen%''     THEN ''300202002''' + CHAR(13) + CHAR(10) + N'      WHEN val LIKE ''%Stupor%''       THEN ''450847001''' + CHAR(13) + CHAR(10) + N'      WHEN val LIKE ''%Coma%''        THEN ''422768004''' + CHAR(13) + CHAR(10) + N'      WHEN val LIKE ''%Apatis%''       THEN ''130987000''' + CHAR(13) + CHAR(10) + N'      WHEN val LIKE ''%Delirium%''     THEN ''2776000''' + CHAR(13) + CHAR(10) + N'      ELSE NULL' + CHAR(13) + CHAR(10) + N'  END AS snomed_kode,' + CHAR(13) + CHAR(10) + N'  CASE ' + CHAR(13) + CHAR(10) + N'      WHEN val LIKE ''%Composmentis%'' THEN ''Mentally alert''' + CHAR(13) + CHAR(10) + N'      WHEN val LIKE ''%Somnolen%''     THEN ''Response to voice''' + CHAR(13) + CHAR(10) + N'      WHEN val LIKE ''%Stupor%''       THEN ''Responds to pain''' + CHAR(13) + CHAR(10) + N'      WHEN val LIKE ''%Coma%''         THEN ''Unresponsive''' + CHAR(13) + CHAR(10) + N'      WHEN val LIKE ''%Apatis%''       THEN ''Acute confusion''' + CHAR(13) + CHAR(10) + N'      WHEN val LIKE ''%Delirium%''     THEN ''Delirium''' + CHAR(13) + CHAR(10) + N'      ELSE NULL' + CHAR(13) + CHAR(10) + N'  END AS snomed_term' + CHAR(13) + CHAR(10) + N'FROM (' + CHAR(13) + CHAR(10) + N'    SELECT TOP 1' + CHAR(13) + CHAR(10) + N'        LTRIM(RTRIM(JSON_VALUE(pa.PhysicalExam, ''$.Consciousness.ConsciousnessDescription''))) AS val' + CHAR(13) + CHAR(10) + N'    FROM PatientAssessment AS pa' + CHAR(13) + CHAR(10) + N'    WHERE pa.registrationno = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'    ORDER BY pa.CreatedDateTime DESC' + CHAR(13) + CHAR(10) + N') AS extracted',NULL);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'Location_Ruang_Bed',0,N'sql',N'SELECT TOP 1 CAST(b.SatuSehatBridgingID AS VARCHAR(50)) AS SatuSehatBridgingID, b.SatuSehatBridgingName FROM BedStatusHistory AS bsh ' + CHAR(13) + CHAR(10) + N'INNER JOIN bed AS b ON bsh.BedID = b.BedID' + CHAR(13) + CHAR(10) + N'WHERE bsh.RegistrationNo = ''@RegistrationNo''',0);
