INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'PatientDiagnose',1,N'sql',N'SELECT DiagnoseID, DiagnosisText' + CHAR(13) + CHAR(10) + N'FROM (' + CHAR(13) + CHAR(10) + N'    SELECT ' + CHAR(13) + CHAR(10) + N'        rimd.DiagnoseID,' + CHAR(13) + CHAR(10) + N'        rimd.DiagnosisText,' + CHAR(13) + CHAR(10) + N'        rimd.SRDiagnoseType,' + CHAR(13) + CHAR(10) + N'        ROW_NUMBER() OVER (' + CHAR(13) + CHAR(10) + N'            PARTITION BY rimd.SRDiagnoseType' + CHAR(13) + CHAR(10) + N'            ORDER BY rimd.LastUpdateDateTime DESC' + CHAR(13) + CHAR(10) + N'        ) AS rn' + CHAR(13) + CHAR(10) + N'    FROM RegistrationInfoMedicDiagnose AS rimd' + CHAR(13) + CHAR(10) + N'    WHERE ' + CHAR(13) + CHAR(10) + N'        rimd.RegistrationNo = ''@RegistrationNo'' AND' + CHAR(13) + CHAR(10) + N'        rimd.IsVoid = 0' + CHAR(13) + CHAR(10) + N') AS Diagnoses' + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    SRDiagnoseType != ''DiagnoseType-001'' OR ' + CHAR(13) + CHAR(10) + N'    (SRDiagnoseType = ''DiagnoseType-001'' AND rn = 1)',1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'PatientDiagnose_Date',0,N'sql',N'SELECT DiagnoseDateTime' + CHAR(13) + CHAR(10) + N'FROM (' + CHAR(13) + CHAR(10) + N'    SELECT ' + CHAR(13) + CHAR(10) + N'        rimd.DiagnoseID,' + CHAR(13) + CHAR(10) + N'        rimd.DiagnosisText,' + CHAR(13) + CHAR(10) + N'        rimd.SRDiagnoseType,' + CHAR(13) + CHAR(10) + N'        rimd.DiagnoseDateTime,' + CHAR(13) + CHAR(10) + N'        ROW_NUMBER() OVER (' + CHAR(13) + CHAR(10) + N'            PARTITION BY rimd.SRDiagnoseType' + CHAR(13) + CHAR(10) + N'            ORDER BY rimd.LastUpdateDateTime DESC' + CHAR(13) + CHAR(10) + N'        ) AS rn' + CHAR(13) + CHAR(10) + N'    FROM RegistrationInfoMedicDiagnose AS rimd' + CHAR(13) + CHAR(10) + N'    WHERE ' + CHAR(13) + CHAR(10) + N'        rimd.RegistrationNo = ''@RegistrationNo'' AND' + CHAR(13) + CHAR(10) + N'        rimd.IsVoid = 0' + CHAR(13) + CHAR(10) + N') AS Diagnoses' + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    SRDiagnoseType != ''DiagnoseType-001'' OR ' + CHAR(13) + CHAR(10) + N'    (SRDiagnoseType = ''DiagnoseType-001'' AND rn = 1)',1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'PatientDrug',1,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    COALESCE(ib1.BridgingID, ib2.BridgingID) AS ItemID,' + CHAR(13) + CHAR(10) + N'    COALESCE(ib1.BridgingName, ib2.BridgingName) AS NamaItem' + CHAR(13) + CHAR(10) + N'FROM TransPrescription AS tp' + CHAR(13) + CHAR(10) + N'INNER JOIN TransPrescriptionItem AS tpi' + CHAR(13) + CHAR(10) + N'    ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemBridging AS ib1' + CHAR(13) + CHAR(10) + N'    ON ib1.ItemID = tpi.ItemID AND ib1.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = '''')' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemBridging AS ib2' + CHAR(13) + CHAR(10) + N'    ON ib2.ItemID = tpi.ItemInterventionID AND ib2.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NOT NULL AND tpi.ItemInterventionID <> '''')' + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    tp.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'    AND tp.IsVoid = 0' + CHAR(13) + CHAR(10) + N'    AND tpi.IsVoid = 0' + CHAR(13) + CHAR(10) + N'    AND tp.IsApproval = 1' + CHAR(13) + CHAR(10) + N'    AND tpi.IsApprove = 1' + CHAR(13) + CHAR(10) + N'    AND tpi.IsCompound = 0',1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'PatientDrugHome',1,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    COALESCE(ib1.BridgingID, ib2.BridgingID) AS ItemID,' + CHAR(13) + CHAR(10) + N'    COALESCE(ib1.BridgingName, ib2.BridgingName) AS NamaItem' + CHAR(13) + CHAR(10) + N'FROM TransPrescription AS tp' + CHAR(13) + CHAR(10) + N'INNER JOIN TransPrescriptionItem AS tpi' + CHAR(13) + CHAR(10) + N'    ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemBridging AS ib1' + CHAR(13) + CHAR(10) + N'    ON ib1.ItemID = tpi.ItemID AND ib1.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = '''')' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemBridging AS ib2' + CHAR(13) + CHAR(10) + N'    ON ib2.ItemID = tpi.ItemInterventionID AND ib1.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NOT NULL AND tpi.ItemInterventionID <> '''')' + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    tp.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'    AND tp.IsVoid = 0' + CHAR(13) + CHAR(10) + N'    AND tpi.IsVoid = 0' + CHAR(13) + CHAR(10) + N'    AND tp.IsApproval = 1' + CHAR(13) + CHAR(10) + N'    AND tpi.IsApprove = 1' + CHAR(13) + CHAR(10) + N'    AND tpi.IsCompound = 0' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'PatientEducation',1,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    STUFF((' + CHAR(13) + CHAR(10) + N'        SELECT ''. '' + asri.ItemName' + CHAR(13) + CHAR(10) + N'        FROM PatientEducationLine AS pel' + CHAR(13) + CHAR(10) + N'        INNER JOIN AppStandardReferenceItem AS asri ' + CHAR(13) + CHAR(10) + N'            ON asri.ItemID = pel.SRPatientEducation' + CHAR(13) + CHAR(10) + N'        WHERE pel.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'          AND asri.StandardReferenceID = ''PatientEducation''' + CHAR(13) + CHAR(10) + N'        FOR XML PATH(''''), TYPE).value(''.'', ''NVARCHAR(MAX)'')' + CHAR(13) + CHAR(10) + N'    , 1, 2, '''') AS PatientEducation' + CHAR(13) + CHAR(10),0);
