VALUES(0,N'-',1,N'PhysicalGenitaliaNarrative',1,N'sql',N'SELECT TOP 1' + CHAR(13) + CHAR(10) + N'  CASE ' + CHAR(13) + CHAR(10) + N'    WHEN ''{{Patient_Sex}}'' = ''M'' THEN' + CHAR(13) + CHAR(10) + N'      CONCAT_WS('' | '',' + CHAR(13) + CHAR(10) + N'        CASE' + CHAR(13) + CHAR(10) + N'          WHEN JSON_VALUE(PhysicalExam, ''$.GenitaliaAndAnus.IsAbNormal'') = ''true''' + CHAR(13) + CHAR(10) + N'            THEN ''Genitalia Abnormal: '' + ISNULL(JSON_VALUE(PhysicalExam, ''$.GenitaliaAndAnus.Notes''), '''')' + CHAR(13) + CHAR(10) + N'          ELSE' + CHAR(13) + CHAR(10) + N'            ''Genitalia Normal: '' + ISNULL(JSON_VALUE(PhysicalExam, ''$.GenitaliaAndAnus.Notes''), '''')' + CHAR(13) + CHAR(10) + N'        END,' + CHAR(13) + CHAR(10) + N'        CASE' + CHAR(13) + CHAR(10) + N'          WHEN JSON_VALUE(PhysicalExam, ''$.GenitaliaPenis.IsAbNormal'') = ''true''' + CHAR(13) + CHAR(10) + N'            THEN ''Penis Abnormal: '' + ISNULL(JSON_VALUE(PhysicalExam, ''$.GenitaliaPenis.Notes''), '''')' + CHAR(13) + CHAR(10) + N'          ELSE' + CHAR(13) + CHAR(10) + N'            ''Penis Normal: '' + ISNULL(JSON_VALUE(PhysicalExam, ''$.GenitaliaPenis.Notes''), '''')' + CHAR(13) + CHAR(10) + N'        END,' + CHAR(13) + CHAR(10) + N'        CASE' + CHAR(13) + CHAR(10) + N'          WHEN JSON_VALUE(PhysicalExam, ''$.GenitaliaTestis.IsAbNormal'') = ''true''' + CHAR(13) + CHAR(10) + N'            THEN ''Testis Abnormal: '' + ISNULL(JSON_VALUE(PhysicalExam, ''$.GenitaliaTestis.Notes''), '''')' + CHAR(13) + CHAR(10) + N'          ELSE' + CHAR(13) + CHAR(10) + N'            ''Testis Normal: '' + ISNULL(JSON_VALUE(PhysicalExam, ''$.GenitaliaTestis.Notes''), '''')' + CHAR(13) + CHAR(10) + N'        END' + CHAR(13) + CHAR(10) + N'      )' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + N'    WHEN ''{{Patient_Sex}}'' = ''F'' THEN' + CHAR(13) + CHAR(10) + N'      CONCAT_WS('' | '',' + CHAR(13) + CHAR(10) + N'        CASE' + CHAR(13) + CHAR(10) + N'          WHEN JSON_VALUE(PhysicalExam, ''$.GenitaliaAndAnus.IsAbNormal'') = ''true''' + CHAR(13) + CHAR(10) + N'            THEN ''Genitalia Abnormal: '' + ISNULL(JSON_VALUE(PhysicalExam, ''$.GenitaliaAndAnus.Notes''), '''')' + CHAR(13) + CHAR(10) + N'          ELSE' + CHAR(13) + CHAR(10) + N'            ''Genitalia Normal: '' + ISNULL(JSON_VALUE(PhysicalExam, ''$.GenitaliaAndAnus.Notes''), '''')' + CHAR(13) + CHAR(10) + N'        END,' + CHAR(13) + CHAR(10) + N'        CASE' + CHAR(13) + CHAR(10) + N'          WHEN JSON_VALUE(PhysicalExam, ''$.GenitaliaLabiaMinor.IsAbNormal'') = ''true''' + CHAR(13) + CHAR(10) + N'            THEN ''Labia Minor Abnormal: '' + ISNULL(JSON_VALUE(PhysicalExam, ''$.GenitaliaLabiaMinor.Notes''), '''')' + CHAR(13) + CHAR(10) + N'          ELSE' + CHAR(13) + CHAR(10) + N'            ''Labia Minor Normal: '' + ISNULL(JSON_VALUE(PhysicalExam, ''$.GenitaliaLabiaMinor.Notes''), '''')' + CHAR(13) + CHAR(10) + N'        END' + CHAR(13) + CHAR(10) + N'      )' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + N'    ELSE NULL' + CHAR(13) + CHAR(10) + N'  END AS genitalia_status' + CHAR(13) + CHAR(10) + N'FROM PatientAssessment' + CHAR(13) + CHAR(10) + N'WHERE registrationno = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'ORDER BY CreatedDateTime DESC',NULL);
