VALUES(0,N'-',1,N'Planning',1,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    COALESCE(' + CHAR(13) + CHAR(10) + N'        NULLIF(r.MedicationPlanning, ''''),' + CHAR(13) + CHAR(10) + N'        NULLIF(rim.info4, ''''),' + CHAR(13) + CHAR(10) + N'        ''''' + CHAR(13) + CHAR(10) + N'    ) AS FinalResult' + CHAR(13) + CHAR(10) + N'FROM' + CHAR(13) + CHAR(10) + N'    (SELECT MedicationPlanning' + CHAR(13) + CHAR(10) + N'     FROM Registration' + CHAR(13) + CHAR(10) + N'     WHERE RegistrationNo = ''@RegistrationNo'') AS r' + CHAR(13) + CHAR(10) + N'FULL OUTER JOIN' + CHAR(13) + CHAR(10) + N'    (SELECT TOP 1 info4' + CHAR(13) + CHAR(10) + N'     FROM RegistrationInfoMedic' + CHAR(13) + CHAR(10) + N'     WHERE RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'       AND SRMedicalNotesInputType = ''SOAP''' + CHAR(13) + CHAR(10) + N'     ORDER BY DateTimeInfo DESC) AS rim' + CHAR(13) + CHAR(10) + N'ON 1 = 1' + CHAR(13) + CHAR(10),NULL);
