VALUES(0,N'-',1,N'Practitioner_Procedure',0,N'sql',N'SELECT pb.BridgingID,pb.BridgingName FROM EpisodeProcedure AS ep INNER JOIN ParamedicBridging AS pb ON pb.ParamedicID = ep.ParamedicID ' + CHAR(13) + CHAR(10) + N'AND pb.SRBridgingType = ''{{SatuSehatBridgingTypeID}}'' WHERE ep.RegistrationNo = ''@RegistrationNo'' AND ep.IsVoid = 0 ',1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'PractitionerLab_Specimen',0,N'sql',N'SELECT pb.BridgingID,pb.BridgingName FROM TransCharges AS tc INNER JOIN TransChargesItem AS tci ON tci.TransactionNo = tc.TransactionNo INNER JOIN ParamedicBridging AS pb ON pb.ParamedicID = tci.ParamedicID WHERE tc.RegistrationNo = ''@RegistrationNo'' AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'') AND tci.IsOrderRealization = 1 AND tci.IsVoid = 0 AND tc.IsOrder = 1 AND tc.IsApproved = 1 AND pb.SRBridgingType = ''{{SatuSehatBridgingTypeID}}'' AND tci.SRCollectMethod IS NOT NULL AND tci.SRCollectMethod <> ''''      ' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'PractitionerLabSingleItem',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    pb.BridgingID,' + CHAR(13) + CHAR(10) + N'    pb.BridgingName' + CHAR(13) + CHAR(10) + N'FROM TransCharges AS tc' + CHAR(13) + CHAR(10) + N'INNER JOIN TransChargesItem AS tci' + CHAR(13) + CHAR(10) + N'    ON tci.TransactionNo = tc.TransactionNo' + CHAR(13) + CHAR(10) + N'INNER JOIN ParamedicBridging AS pb' + CHAR(13) + CHAR(10) + N'    ON pb.ParamedicID = tci.ParamedicID' + CHAR(13) + CHAR(10) + N'WHERE tc.RegistrationNo   = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'  AND tc.ToServiceUnitID  IN (''{{ServiceUnitLaboratoryID}}'')' + CHAR(13) + CHAR(10) + N'  AND tci.IsOrderRealization = 1' + CHAR(13) + CHAR(10) + N'  AND tci.IsVoid = 0' + CHAR(13) + CHAR(10) + N'  AND tc.IsOrder = 1' + CHAR(13) + CHAR(10) + N'  AND tc.IsApproved = 1' + CHAR(13) + CHAR(10) + N'  AND tci.SRCollectMethod IS NOT NULL' + CHAR(13) + CHAR(10) + N'  AND LTRIM(RTRIM(tci.SRCollectMethod)) <> ''''' + CHAR(13) + CHAR(10) + N'  AND pb.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'  AND (tci.ParentNo IS NULL OR LTRIM(RTRIM(tci.ParentNo)) = '''')   ' + CHAR(13) + CHAR(10) + N'  AND NOT EXISTS (                                                ' + CHAR(13) + CHAR(10) + N'        SELECT 1' + CHAR(13) + CHAR(10) + N'        FROM TransChargesItem AS child' + CHAR(13) + CHAR(10) + N'        WHERE child.TransactionNo = tci.TransactionNo' + CHAR(13) + CHAR(10) + N'          AND child.ParentNo = tci.SequenceNo' + CHAR(13) + CHAR(10) + N'    )' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'PractitionerPresc',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    COALESCE(pb1.BridgingID, pb2.BridgingID) AS BridgingID,' + CHAR(13) + CHAR(10) + N'    COALESCE(pb1.BridgingName, pb2.BridgingName) AS BridgingName' + CHAR(13) + CHAR(10) + N'FROM TransPrescription tp' + CHAR(13) + CHAR(10) + N'INNER JOIN TransPrescriptionItem tpi ' + CHAR(13) + CHAR(10) + N'    ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'LEFT JOIN AppUser au ' + CHAR(13) + CHAR(10) + N'    ON tp.DeliverByUserID = au.UserID' + CHAR(13) + CHAR(10) + N'OUTER APPLY (' + CHAR(13) + CHAR(10) + N'    SELECT TOP 1 BridgingID, BridgingName' + CHAR(13) + CHAR(10) + N'    FROM ParamedicBridging' + CHAR(13) + CHAR(10) + N'    WHERE ParamedicID = au.ParamedicID' + CHAR(13) + CHAR(10) + N'      AND SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N') pb1' + CHAR(13) + CHAR(10) + N'OUTER APPLY (' + CHAR(13) + CHAR(10) + N'    SELECT TOP 1 BridgingID, BridgingName' + CHAR(13) + CHAR(10) + N'    FROM ParamedicBridging' + CHAR(13) + CHAR(10) + N'    WHERE ParamedicID = tp.ParamedicID' + CHAR(13) + CHAR(10) + N'      AND SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'      AND pb1.BridgingID IS NULL' + CHAR(13) + CHAR(10) + N') pb2' + CHAR(13) + CHAR(10) + N'WHERE tp.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'  AND tp.IsVoid = 0' + CHAR(13) + CHAR(10) + N'  AND tpi.IsVoid = 0' + CHAR(13) + CHAR(10) + N'  AND tp.IsApproval = 1' + CHAR(13) + CHAR(10) + N'  AND tpi.IsApprove = 1' + CHAR(13) + CHAR(10) + N'  AND tpi.IsCompound = 0',1);
