INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'Prognosis',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    COALESCE(t.[Prognosis-code], ''170968001'') AS [Prognosis-code],' + CHAR(13) + CHAR(10) + N'    COALESCE(t.[Prognosis-name], ''Prognosis good'') AS [Prognosis-name]' + CHAR(13) + CHAR(10) + N'FROM (VALUES(1)) AS v(dummy)' + CHAR(13) + CHAR(10) + N'OUTER APPLY (' + CHAR(13) + CHAR(10) + N'    SELECT TOP 1' + CHAR(13) + CHAR(10) + N'        CASE' + CHAR(13) + CHAR(10) + N'            WHEN mds.SRDischargeCondition IN (''E01'', ''I01'', ''O01'') THEN ''170968001''' + CHAR(13) + CHAR(10) + N'            WHEN mds.SRDischargeCondition IN (''E02'', ''I02'', ''O02'') THEN ''65872000''' + CHAR(13) + CHAR(10) + N'            WHEN mds.SRDischargeCondition IN (''E03'', ''I03'', ''O03'') THEN ''67334001''' + CHAR(13) + CHAR(10) + N'            ELSE ''170968001''' + CHAR(13) + CHAR(10) + N'        END AS [Prognosis-code],' + CHAR(13) + CHAR(10) + N'        CASE' + CHAR(13) + CHAR(10) + N'            WHEN mds.SRDischargeCondition IN (''E01'', ''I01'', ''O01'') THEN ''Prognosis good''' + CHAR(13) + CHAR(10) + N'            WHEN mds.SRDischargeCondition IN (''E02'', ''I02'', ''O02'') THEN ''Fair prognosis''' + CHAR(13) + CHAR(10) + N'            WHEN mds.SRDischargeCondition IN (''E03'', ''I03'', ''O03'') THEN ''Guarded prognosis''' + CHAR(13) + CHAR(10) + N'            ELSE ''Prognosis good''' + CHAR(13) + CHAR(10) + N'        END AS [Prognosis-name]' + CHAR(13) + CHAR(10) + N'    FROM MedicalDischargeSummary AS mds' + CHAR(13) + CHAR(10) + N'    WHERE mds.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N') t',0);
