VALUES(0,N'-',1,N'ResponDataAllObservationLab',0,N'sql',N'SELECT' + CHAR(13) + CHAR(10) + N'    ''{ "resourceType": "Bundle", "type": "transaction-response", "entry": ['' +' + CHAR(13) + CHAR(10) + N'    ISNULL(' + CHAR(13) + CHAR(10) + N'        STUFF((' + CHAR(13) + CHAR(10) + N'            SELECT' + CHAR(13) + CHAR(10) + N'                CASE ' + CHAR(13) + CHAR(10) + N'                    WHEN CHARINDEX(''['', ssi.RespondData) > 0' + CHAR(13) + CHAR(10) + N'                         AND CHARINDEX(''],"resourceType"'', ssi.RespondData) > CHARINDEX(''['', ssi.RespondData)' + CHAR(13) + CHAR(10) + N'                         AND LEN(LTRIM(RTRIM(ssi.RespondData))) > 0' + CHAR(13) + CHAR(10) + N'                    THEN' + CHAR(13) + CHAR(10) + N'                        '','' +' + CHAR(13) + CHAR(10) + N'                        SUBSTRING(' + CHAR(13) + CHAR(10) + N'                            ssi.RespondData,' + CHAR(13) + CHAR(10) + N'                            CHARINDEX(''['', ssi.RespondData) + 1,' + CHAR(13) + CHAR(10) + N'                            CHARINDEX(''],"resourceType"'', ssi.RespondData) - CHARINDEX(''['', ssi.RespondData) - 1' + CHAR(13) + CHAR(10) + N'                        )' + CHAR(13) + CHAR(10) + N'                    ELSE ''''' + CHAR(13) + CHAR(10) + N'                END' + CHAR(13) + CHAR(10) + N'            FROM SatuSehatILPPreparation ssi' + CHAR(13) + CHAR(10) + N'            WHERE' + CHAR(13) + CHAR(10) + N'                ssi.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'                AND ssi.TestNo IN (''10.1.4.01'',''10.1.4.02'')' + CHAR(13) + CHAR(10) + N'                AND ssi.RespondData IS NOT NULL' + CHAR(13) + CHAR(10) + N'                AND LTRIM(RTRIM(ssi.RespondData)) <> ''''' + CHAR(13) + CHAR(10) + N'            FOR XML PATH(''''), TYPE' + CHAR(13) + CHAR(10) + N'        ).value(''.'', ''NVARCHAR(MAX)''), 1, 1, ''''), ''''' + CHAR(13) + CHAR(10) + N'    ) +' + CHAR(13) + CHAR(10) + N'    ''], "total": '' +' + CHAR(13) + CHAR(10) + N'    CAST(' + CHAR(13) + CHAR(10) + N'        ISNULL((' + CHAR(13) + CHAR(10) + N'            SELECT ' + CHAR(13) + CHAR(10) + N'                SUM(' + CHAR(13) + CHAR(10) + N'                    (LEN(ssi2.RespondData) - LEN(REPLACE(ssi2.RespondData, ''{"response":'', '''')))' + CHAR(13) + CHAR(10) + N'                    / NULLIF(LEN(''{"response":''), 0)' + CHAR(13) + CHAR(10) + N'                )' + CHAR(13) + CHAR(10) + N'            FROM SatuSehatILPPreparation ssi2' + CHAR(13) + CHAR(10) + N'            WHERE' + CHAR(13) + CHAR(10) + N'                ssi2.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'                AND ssi2.TestNo IN (''10.1.4.01'',''10.1.4.02'')' + CHAR(13) + CHAR(10) + N'                AND ssi2.RespondData IS NOT NULL' + CHAR(13) + CHAR(10) + N'                AND LTRIM(RTRIM(ssi2.RespondData)) <> ''''' + CHAR(13) + CHAR(10) + N'        ), 0) AS VARCHAR(10)' + CHAR(13) + CHAR(10) + N'    ) +' + CHAR(13) + CHAR(10) + N'    '' }'' AS MergedJson' + CHAR(13) + CHAR(10) + N'FROM (SELECT 1 AS Dummy) AS X' + CHAR(13) + CHAR(10),0);
