VALUES(0,N'-',1,N'ServiceUnitLaboratoryID',0,N'sql',N'SELECT LTRIM(RTRIM(' + CHAR(13) + CHAR(10) + N'         SUBSTRING(' + CHAR(13) + CHAR(10) + N'           ap.ParameterValue,' + CHAR(13) + CHAR(10) + N'           s.number,' + CHAR(13) + CHAR(10) + N'           NULLIF(CHARINDEX('','', ap.ParameterValue + '','', s.number) - s.number, -1)' + CHAR(13) + CHAR(10) + N'         )' + CHAR(13) + CHAR(10) + N'       )) AS ServiceUnitID' + CHAR(13) + CHAR(10) + N'FROM AppParameter ap' + CHAR(13) + CHAR(10) + N'JOIN master.dbo.spt_values s' + CHAR(13) + CHAR(10) + N'  ON s.type = ''P''' + CHAR(13) + CHAR(10) + N' AND s.number BETWEEN 1 AND LEN(ISNULL(ap.ParameterValue, ''''))' + CHAR(13) + CHAR(10) + N'WHERE ap.ParameterID = ''ServiceUnitLaboratoryIdArray''' + CHAR(13) + CHAR(10) + N'  AND ISNULL(ap.ParameterValue, '''') <> ''''' + CHAR(13) + CHAR(10) + N'  AND SUBSTRING('','' + ap.ParameterValue, s.number, 1) = '',''' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + N'UNION' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + N'SELECT LTRIM(RTRIM(ap.ParameterValue)) AS ServiceUnitID' + CHAR(13) + CHAR(10) + N'FROM AppParameter ap' + CHAR(13) + CHAR(10) + N'WHERE ap.ParameterID = ''ServiceUnitLaboratoryId''' + CHAR(13) + CHAR(10),1);
