INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'ZatAktifKfa',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = ''''' + CHAR(13) + CHAR(10) + N'            THEN ai1.kfa_code' + CHAR(13) + CHAR(10) + N'        ELSE ai2.kfa_code' + CHAR(13) + CHAR(10) + N'    END AS zat_aktif_code,' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = ''''' + CHAR(13) + CHAR(10) + N'            THEN ai1.zat_aktif' + CHAR(13) + CHAR(10) + N'        ELSE ai2.zat_aktif' + CHAR(13) + CHAR(10) + N'    END AS zat_aktif,' + CHAR(13) + CHAR(10) + N'    tpi.PrescriptionNo + ''-'' + CAST(tpi.SequenceNo AS VARCHAR) AS TransSeq' + CHAR(13) + CHAR(10) + N'FROM TransPrescription AS tp' + CHAR(13) + CHAR(10) + N'INNER JOIN TransPrescriptionItem AS tpi' + CHAR(13) + CHAR(10) + N'    ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemBridging AS ib1' + CHAR(13) + CHAR(10) + N'    ON ib1.ItemID = tpi.ItemID AND ib1.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = '''')' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemBridging AS ib2' + CHAR(13) + CHAR(10) + N'    ON ib2.ItemID = tpi.ItemInterventionID AND ib2.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NOT NULL AND tpi.ItemInterventionID <> '''')' + CHAR(13) + CHAR(10) + N'LEFT JOIN SatuSehatKfa AS ssk1' + CHAR(13) + CHAR(10) + N'    ON ssk1.ss_uuid = ib1.BridgingID' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = '''')' + CHAR(13) + CHAR(10) + N'LEFT JOIN SatuSehatKfa AS ssk2' + CHAR(13) + CHAR(10) + N'    ON ssk2.ss_uuid = ib2.BridgingID' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NOT NULL AND tpi.ItemInterventionID <> '''')' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + N'OUTER APPLY OPENJSON(ssk1.ss_result, ''$.data.active_ingredients'')' + CHAR(13) + CHAR(10) + N'WITH (' + CHAR(13) + CHAR(10) + N'    kfa_code   VARCHAR(20)   ''$.kfa_code'',' + CHAR(13) + CHAR(10) + N'    zat_aktif  NVARCHAR(200) ''$.zat_aktif''' + CHAR(13) + CHAR(10) + N') AS ai1' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + N'OUTER APPLY OPENJSON(ssk2.ss_result, ''$.data.active_ingredients'')' + CHAR(13) + CHAR(10) + N'WITH (' + CHAR(13) + CHAR(10) + N'    kfa_code   VARCHAR(20)   ''$.kfa_code'',' + CHAR(13) + CHAR(10) + N'    zat_aktif  NVARCHAR(200) ''$.zat_aktif''' + CHAR(13) + CHAR(10) + N') AS ai2' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    tp.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'    AND tp.IsVoid = 0' + CHAR(13) + CHAR(10) + N'    AND tpi.IsVoid = 0' + CHAR(13) + CHAR(10) + N'    AND tp.IsApproval = 1' + CHAR(13) + CHAR(10) + N'    AND tpi.IsApprove = 1' + CHAR(13) + CHAR(10) + N'    AND tpi.IsCompound = 0' + CHAR(13) + CHAR(10) + N'ORDER BY ' + CHAR(13) + CHAR(10) + N'    tpi.CreatedDateTime' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'-',1,N'ZatAktifKfaHome',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    JSON_VALUE(ssk.ss_result, ''$.data.active_ingredients[0].kfa_code'') AS zat_aktif_code,' + CHAR(13) + CHAR(10) + N'    JSON_VALUE(ssk.ss_result, ''$.data.active_ingredients[0].zat_aktif'') AS zat_aktif' + CHAR(13) + CHAR(10) + N'FROM MedicationReceive AS mr' + CHAR(13) + CHAR(10) + N'INNER JOIN TransPrescriptionItem AS tpi' + CHAR(13) + CHAR(10) + N'    ON tpi.PrescriptionNo = mr.RefTransactionNo' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemBridging AS ib' + CHAR(13) + CHAR(10) + N'    ON ib.ItemID = mr.ItemID AND ib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'LEFT JOIN SatuSehatKfa AS ssk' + CHAR(13) + CHAR(10) + N'    ON ssk.ss_uuid = ib.BridgingID' + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    mr.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'    AND mr.IsVoid = 0' + CHAR(13) + CHAR(10) + N'    AND mr.IsBroughtHome = 1' + CHAR(13) + CHAR(10) + N'    AND tpi.IsCompound = 0' + CHAR(13) + CHAR(10) + N'    AND tpi.ItemID = mr.ItemID' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'03.6',1,N'DrugAllergyRecordDate',0,N'sql',N'SELECT pa.LastUpdateDateTime FROM PatientAllergy AS pa WHERE pa.SRAllergyCategory = ''Medication'' and pa.PatientID = ''{{PatientID_HIS}}''',1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'03.9.0',1,N'DosageFormPat',0,N'sql',N'SELECT' + CHAR(13) + CHAR(10) + N'    x.dosage_form_code,' + CHAR(13) + CHAR(10) + N'    x.dosage_form_name' + CHAR(13) + CHAR(10) + N'FROM (' + CHAR(13) + CHAR(10) + N'    SELECT' + CHAR(13) + CHAR(10) + N'        mr.RegistrationNo,' + CHAR(13) + CHAR(10) + N'        JSON_VALUE(ssk.ss_result, ''$.data.dosage_form.code'') AS dosage_form_code,' + CHAR(13) + CHAR(10) + N'        JSON_VALUE(ssk.ss_result, ''$.data.dosage_form.name'') AS dosage_form_name,' + CHAR(13) + CHAR(10) + N'        mr.ItemID' + CHAR(13) + CHAR(10) + N'    FROM MedicationReceiveFromPatient AS mrfp' + CHAR(13) + CHAR(10) + N'    INNER JOIN MedicationReceive AS mr' + CHAR(13) + CHAR(10) + N'        ON mrfp.MedicationReceiveNo = mr.MedicationReceiveNo' + CHAR(13) + CHAR(10) + N'    OUTER APPLY (' + CHAR(13) + CHAR(10) + N'        SELECT TOP 1 ib.BridgingID' + CHAR(13) + CHAR(10) + N'        FROM ItemBridging AS ib' + CHAR(13) + CHAR(10) + N'        WHERE ib.ItemID = mr.ItemID' + CHAR(13) + CHAR(10) + N'          AND ib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'    ) AS ib' + CHAR(13) + CHAR(10) + N'    OUTER APPLY (' + CHAR(13) + CHAR(10) + N'        SELECT TOP 1 ssk.ss_result' + CHAR(13) + CHAR(10) + N'        FROM SatuSehatKfa AS ssk' + CHAR(13) + CHAR(10) + N'        WHERE ssk.ss_uuid = ib.BridgingID' + CHAR(13) + CHAR(10) + N'    ) AS ssk' + CHAR(13) + CHAR(10) + N'    WHERE mr.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'      AND mr.IsVoid = 0' + CHAR(13) + CHAR(10) + N') AS x',1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'03.9.0',1,N'MedicationReceiveNoFromPat',0,N'sql',N'SELECT' + CHAR(13) + CHAR(10) + N'    mrfp.MedicationReceiveNo' + CHAR(13) + CHAR(10) + N'FROM MedicationReceive AS mr' + CHAR(13) + CHAR(10) + N'INNER JOIN MedicationReceiveFromPatient AS mrfp' + CHAR(13) + CHAR(10) + N'    ON mrfp.MedicationReceiveNo = mr.MedicationReceiveNo' + CHAR(13) + CHAR(10) + N'OUTER APPLY (' + CHAR(13) + CHAR(10) + N'    SELECT TOP 1' + CHAR(13) + CHAR(10) + N'        ib.BridgingID,' + CHAR(13) + CHAR(10) + N'        ib.BridgingName' + CHAR(13) + CHAR(10) + N'    FROM ItemBridging AS ib' + CHAR(13) + CHAR(10) + N'    WHERE ib.ItemID = mr.ItemID' + CHAR(13) + CHAR(10) + N'      AND ib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N') AS ib' + CHAR(13) + CHAR(10) + N'OUTER APPLY (' + CHAR(13) + CHAR(10) + N'    SELECT TOP 1' + CHAR(13) + CHAR(10) + N'        skfa.ss_uuid,' + CHAR(13) + CHAR(10) + N'        skfa.ss_nama' + CHAR(13) + CHAR(10) + N'    FROM SatuSehatKFA AS skfa' + CHAR(13) + CHAR(10) + N'    WHERE skfa.ss_uuid = ib.BridgingID' + CHAR(13) + CHAR(10) + N') AS skfa' + CHAR(13) + CHAR(10) + N'WHERE mr.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'  AND mr.IsVoid = 0' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'03.9.0',1,N'PatientDrugfromPat',1,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    ib.BridgingID,' + CHAR(13) + CHAR(10) + N'    ib.BridgingName' + CHAR(13) + CHAR(10) + N'FROM MedicationReceive AS mr' + CHAR(13) + CHAR(10) + N'INNER JOIN MedicationReceiveFromPatient AS mrfp ' + CHAR(13) + CHAR(10) + N'    ON mrfp.MedicationReceiveNo = mr.MedicationReceiveNo' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + N'OUTER APPLY (' + CHAR(13) + CHAR(10) + N'    SELECT TOP 1 ib.BridgingID, ib.BridgingName' + CHAR(13) + CHAR(10) + N'    FROM ItemBridging AS ib' + CHAR(13) + CHAR(10) + N'    WHERE ib.ItemID = mr.ItemID' + CHAR(13) + CHAR(10) + N'      AND ib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N') AS ib' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + N'OUTER APPLY (' + CHAR(13) + CHAR(10) + N'    SELECT TOP 1 skfa.ss_uuid, skfa.ss_nama' + CHAR(13) + CHAR(10) + N'    FROM SatuSehatKFA AS skfa' + CHAR(13) + CHAR(10) + N'    WHERE skfa.ss_uuid = ib.BridgingID' + CHAR(13) + CHAR(10) + N') AS skfa' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + N'WHERE mr.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'  AND mr.IsVoid = 0' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'03.9.01',1,N'DrugConsumeMethodFromPat',1,N'sql',N'SELECT ConsumeMethod.SRConsumeMethodName FROM MedicationReceive AS mr  INNER JOIN MedicationReceiveFromPatient AS mrfp      ON mrfp.MedicationReceiveNo = mr.MedicationReceiveNo  OUTER APPLY (      SELECT TOP 1          ib.BridgingID,          ib.BridgingName      FROM ItemBridging AS ib      WHERE ib.ItemID = mr.ItemID        AND ib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''  ) AS ib  OUTER APPLY (      SELECT TOP 1          skfa.ss_uuid,          skfa.ss_nama      FROM SatuSehatKFA AS skfa      WHERE skfa.ss_uuid = ib.BridgingID  ) AS skfa INNER JOIN ConsumeMethod ON mr.SRConsumeMethod = ConsumeMethod.SRConsumeMethod  WHERE mr.RegistrationNo = ''@RegistrationNo''    AND mr.IsVoid = 0  ' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'03.9.01',1,N'DrugIterationQtyFromPat',0,N'sql',N'SELECT ConsumeMethod.IterationQty FROM MedicationReceive AS mr  INNER JOIN MedicationReceiveFromPatient AS mrfp      ON mrfp.MedicationReceiveNo = mr.MedicationReceiveNo  OUTER APPLY (      SELECT TOP 1          ib.BridgingID,          ib.BridgingName      FROM ItemBridging AS ib      WHERE ib.ItemID = mr.ItemID        AND ib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''  ) AS ib  OUTER APPLY (      SELECT TOP 1          skfa.ss_uuid,          skfa.ss_nama      FROM SatuSehatKFA AS skfa      WHERE skfa.ss_uuid = ib.BridgingID  ) AS skfa INNER JOIN ConsumeMethod ON mr.SRConsumeMethod = ConsumeMethod.SRConsumeMethod  WHERE mr.RegistrationNo = ''@RegistrationNo''    AND mr.IsVoid = 0  ' + CHAR(13) + CHAR(10),1);
