INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'03.9.01',1,N'MedReceiveFromPatDate',0,N'sql',N'SELECT mr.ReceiveDateTime FROM MedicationReceive AS mr  INNER JOIN MedicationReceiveFromPatient AS mrfp      ON mrfp.MedicationReceiveNo = mr.MedicationReceiveNo  OUTER APPLY (      SELECT TOP 1          ib.BridgingID,          ib.BridgingName      FROM ItemBridging AS ib      WHERE ib.ItemID = mr.ItemID        AND ib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''  ) AS ib  OUTER APPLY (      SELECT TOP 1          skfa.ss_uuid,          skfa.ss_nama      FROM SatuSehatKFA AS skfa      WHERE skfa.ss_uuid = ib.BridgingID  ) AS skfa INNER JOIN ConsumeMethod ON mr.SRConsumeMethod = ConsumeMethod.SRConsumeMethod  WHERE mr.RegistrationNo = ''@RegistrationNo''    AND mr.IsVoid = 0  ' + CHAR(13) + CHAR(10),1);
