VALUES(0,N'04.4.03',1,N'BodySurfaceArea',1,N'sql',N'SELECT       ROUND(SQRT(({{BodyWeight}} * {{BodyHeight}}) / 3600.0), 2) AS BSA  FROM Patient p  WHERE p.PatientID = ''{{PatientID_HIS}}''    AND DATEDIFF(YEAR, p.dateOfBirth, GETDATE()) < 18',0);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'07.1.01',1,N'PatientGoal',1,N'sql',N'SELECT TOP 1' + CHAR(13) + CHAR(10) + N'    LTRIM(RTRIM(' + CHAR(13) + CHAR(10) + N'        ISNULL(' + CHAR(13) + CHAR(10) + N'            CASE WHEN rmg.Problem IS NOT NULL AND LTRIM(RTRIM(rmg.Problem)) <> '''' ' + CHAR(13) + CHAR(10) + N'                 THEN ''Pasien mengalami '' + rmg.Problem ' + CHAR(13) + CHAR(10) + N'                 ELSE '''' END, ''''' + CHAR(13) + CHAR(10) + N'        )' + CHAR(13) + CHAR(10) + N'        + ISNULL(' + CHAR(13) + CHAR(10) + N'            CASE WHEN rmg.Planning IS NOT NULL AND LTRIM(RTRIM(rmg.Planning)) <> '''' ' + CHAR(13) + CHAR(10) + N'                 THEN '' dan akan dilakukan '' + rmg.Planning ' + CHAR(13) + CHAR(10) + N'                 ELSE '''' END, ''''' + CHAR(13) + CHAR(10) + N'        )' + CHAR(13) + CHAR(10) + N'        + ISNULL(' + CHAR(13) + CHAR(10) + N'            CASE WHEN rmg.Goal IS NOT NULL AND LTRIM(RTRIM(rmg.Goal)) <> '''' ' + CHAR(13) + CHAR(10) + N'                 THEN '' agar pasien '' + rmg.Goal ' + CHAR(13) + CHAR(10) + N'                 ELSE '''' END, ''''' + CHAR(13) + CHAR(10) + N'        )' + CHAR(13) + CHAR(10) + N'        + ISNULL(' + CHAR(13) + CHAR(10) + N'            CASE WHEN rmg.IterationQty IS NOT NULL AND rmg.SRTimeType IS NOT NULL ' + CHAR(13) + CHAR(10) + N'                 THEN '' dalam jangka waktu '' + CAST(rmg.IterationQty AS VARCHAR(10)) + '' x '' + CAST(rmg.qty AS VARCHAR(10)) + asri.ItemName' + CHAR(13) + CHAR(10) + N'                 ELSE '''' END, ''''' + CHAR(13) + CHAR(10) + N'        )' + CHAR(13) + CHAR(10) + N'    )) AS Deskripsi' + CHAR(13) + CHAR(10) + N'FROM RegistrationMeasuredGoal rmg' + CHAR(13) + CHAR(10) + N'INNER JOIN AppStandardReferenceItem AS asri' + CHAR(13) + CHAR(10) + N'ON asri.ItemID = rmg.SRTimeType' + CHAR(13) + CHAR(10) + N'WHERE rmg.RegistrationNo = ''@RegistrationNo'' AND asri.StandardReferenceID = ''TimeType''' + CHAR(13) + CHAR(10),0);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'10.1.03',1,N'LaboratoryTestValueObservation',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    tci.ResultValue' + CHAR(13) + CHAR(10) + N'FROM TransCharges AS tc' + CHAR(13) + CHAR(10) + N'INNER JOIN TransChargesItem AS tci' + CHAR(13) + CHAR(10) + N'    ON tci.TransactionNo = tc.TransactionNo' + CHAR(13) + CHAR(10) + N'OUTER APPLY (' + CHAR(13) + CHAR(10) + N'    SELECT TOP 1 ' + CHAR(13) + CHAR(10) + N'        ib.BridgingID, ' + CHAR(13) + CHAR(10) + N'        ib.BridgingName' + CHAR(13) + CHAR(10) + N'    FROM ItemBridging AS ib' + CHAR(13) + CHAR(10) + N'    WHERE ib.ItemID = tci.ItemID AND ib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N') AS ib' + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    tc.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'    AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'')' + CHAR(13) + CHAR(10) + N'    AND (' + CHAR(13) + CHAR(10) + N'        (tci.IsOrderRealization = 1 AND tci.IsVoid = 0 AND tc.IsOrder = 1 AND tc.IsApproved = 1)' + CHAR(13) + CHAR(10) + N'        OR (tci.ParentNo IS NOT NULL AND LTRIM(RTRIM(tci.ParentNo)) <> '''')' + CHAR(13) + CHAR(10) + N'    )' + CHAR(13) + CHAR(10) + N'    AND tci.ResultValue IS NOT NULL' + CHAR(13) + CHAR(10) + N'    AND LTRIM(RTRIM(tci.ResultValue)) <> ''''' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'10.1.04',1,N'ItemLaboratoryUnitObservation',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN LEFT(il.SRLaboratoryUnit, 1) = ''×''' + CHAR(13) + CHAR(10) + N'            THEN LTRIM(SUBSTRING(il.SRLaboratoryUnit, 2, LEN(il.SRLaboratoryUnit) - 1))' + CHAR(13) + CHAR(10) + N'        ELSE il.SRLaboratoryUnit' + CHAR(13) + CHAR(10) + N'    END AS SRLaboratoryUnit' + CHAR(13) + CHAR(10) + N'FROM TransCharges AS tc' + CHAR(13) + CHAR(10) + N'INNER JOIN TransChargesItem AS tci' + CHAR(13) + CHAR(10) + N'    ON tc.TransactionNo = tci.TransactionNo' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemBridging AS ib' + CHAR(13) + CHAR(10) + N'    ON ib.ItemID = tci.ItemID AND ib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemLaboratory AS il' + CHAR(13) + CHAR(10) + N'    ON tci.ItemID = il.ItemID' + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    tc.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'    AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'')' + CHAR(13) + CHAR(10) + N'    AND (' + CHAR(13) + CHAR(10) + N'        (tci.IsOrderRealization = 1 AND tci.IsVoid = 0 AND tc.IsOrder = 1 AND tc.IsApproved = 1)' + CHAR(13) + CHAR(10) + N'        OR (tci.ParentNo IS NOT NULL AND LTRIM(RTRIM(tci.ParentNo)) <> '''')' + CHAR(13) + CHAR(10) + N'    )' + CHAR(13) + CHAR(10) + N'    AND tci.ResultValue IS NOT NULL' + CHAR(13) + CHAR(10) + N'    AND LTRIM(RTRIM(tci.ResultValue)) <> ''''' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'10.1.04',1,N'LaboratoryProcedureObservation',1,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    ib.BridgingID,' + CHAR(13) + CHAR(10) + N'    ib.BridgingName' + CHAR(13) + CHAR(10) + N'FROM TransCharges AS tc' + CHAR(13) + CHAR(10) + N'INNER JOIN TransChargesItem AS tci' + CHAR(13) + CHAR(10) + N'    ON tci.TransactionNo = tc.TransactionNo' + CHAR(13) + CHAR(10) + N'OUTER APPLY (' + CHAR(13) + CHAR(10) + N'    SELECT TOP 1 ' + CHAR(13) + CHAR(10) + N'        ib.BridgingID,' + CHAR(13) + CHAR(10) + N'        ib.BridgingName' + CHAR(13) + CHAR(10) + N'    FROM ItemBridging AS ib' + CHAR(13) + CHAR(10) + N'    WHERE ib.ItemID = tci.ItemID AND ib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N') AS ib' + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    tc.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'    AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'')' + CHAR(13) + CHAR(10) + N'    AND (' + CHAR(13) + CHAR(10) + N'        (tci.IsOrderRealization = 1 AND tci.IsVoid = 0 AND tc.IsOrder = 1 AND tc.IsApproved = 1)' + CHAR(13) + CHAR(10) + N'        OR (tci.ParentNo IS NOT NULL AND LTRIM(RTRIM(tci.ParentNo)) <> '''')' + CHAR(13) + CHAR(10) + N'    )' + CHAR(13) + CHAR(10) + N'    AND tci.ResultValue IS NOT NULL' + CHAR(13) + CHAR(10) + N'    AND LTRIM(RTRIM(tci.ResultValue)) <> ''''' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'10.1.04',1,N'LabTestInterpretationObservation',0,N'sql',N'SELECT' + CHAR(13) + CHAR(10) + N'    CASE          ' + CHAR(13) + CHAR(10) + N'        WHEN r.val < d.NormalValueMin THEN ''L''          ' + CHAR(13) + CHAR(10) + N'        WHEN r.val > d.NormalValueMax THEN ''H''          ' + CHAR(13) + CHAR(10) + N'        ELSE ''N''      ' + CHAR(13) + CHAR(10) + N'    END AS Code,      ' + CHAR(13) + CHAR(10) + N'    CASE          ' + CHAR(13) + CHAR(10) + N'        WHEN r.val < d.NormalValueMin THEN ''Low''          ' + CHAR(13) + CHAR(10) + N'        WHEN r.val > d.NormalValueMax THEN ''High''          ' + CHAR(13) + CHAR(10) + N'        ELSE ''NORMAL''      ' + CHAR(13) + CHAR(10) + N'    END AS NAME' + CHAR(13) + CHAR(10) + N'FROM (  ' + CHAR(13) + CHAR(10) + N'    SELECT  ' + CHAR(13) + CHAR(10) + N'        i.ItemID AS ItemID,  ' + CHAR(13) + CHAR(10) + N'        tci.ResultValue AS val  ' + CHAR(13) + CHAR(10) + N'    FROM TransCharges AS tc ' + CHAR(13) + CHAR(10) + N'    INNER JOIN TransChargesItem AS tci  ' + CHAR(13) + CHAR(10) + N'        ON tci.TransactionNo = tc.TransactionNo ' + CHAR(13) + CHAR(10) + N'    LEFT JOIN Item AS i  ' + CHAR(13) + CHAR(10) + N'        ON i.ItemID = tci.ItemID  ' + CHAR(13) + CHAR(10) + N'    WHERE  ' + CHAR(13) + CHAR(10) + N'        tc.RegistrationNo = ''@RegistrationNo''  ' + CHAR(13) + CHAR(10) + N'        AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'')' + CHAR(13) + CHAR(10) + CHAR(9) + CHAR(9) + N'  AND (' + CHAR(13) + CHAR(10) + CHAR(9) + CHAR(9) + CHAR(9) + N'  (tci.IsOrderRealization = 1 AND tci.IsVoid = 0 AND tc.IsOrder = 1 AND tc.IsApproved = 1)' + CHAR(13) + CHAR(10) + CHAR(9) + CHAR(9) + CHAR(9) + N'  OR (tci.ParentNo IS NOT NULL AND LTRIM(RTRIM(tci.ParentNo)) <> '''')' + CHAR(13) + CHAR(10) + CHAR(9) + CHAR(9) + N'  )' + CHAR(13) + CHAR(10) + CHAR(9) + CHAR(9) + N'  AND tci.ResultValue IS NOT NULL' + CHAR(13) + CHAR(10) + CHAR(9) + CHAR(9) + N'  AND LTRIM(RTRIM(tci.ResultValue)) <> '''' ' + CHAR(13) + CHAR(10) + N') r' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemLaboratoryDetail d' + CHAR(13) + CHAR(10) + N'    ON d.ItemID = r.ItemID' + CHAR(13) + CHAR(10) + N'    AND d.Sex = (SELECT Sex FROM Patient WHERE PatientID = ''{{PatientID_HIS}}'')   ' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'10.1.04',1,N'LabTestNormalValueMaxObservation',0,N'sql',CHAR(13) + CHAR(10) + N'SELECT  ' + CHAR(13) + CHAR(10) + N'    tci.ItemID,' + CHAR(13) + CHAR(10) + N'    ISNULL(' + CHAR(13) + CHAR(10) + N'        (' + CHAR(13) + CHAR(10) + N'            SELECT TOP 1 ild.NormalValueMax' + CHAR(13) + CHAR(10) + N'            FROM ItemLaboratoryDetail AS ild' + CHAR(13) + CHAR(10) + N'            WHERE ild.ItemID = tci.ItemID' + CHAR(13) + CHAR(10) + N'              AND ild.Sex = p.Sex' + CHAR(13) + CHAR(10) + N'              AND DATEDIFF(YEAR, p.DateOfBirth, GETDATE()) BETWEEN ild.AgeMin AND ild.AgeMax' + CHAR(13) + CHAR(10) + N'        ),' + CHAR(13) + CHAR(10) + N'        CAST(0 AS DECIMAL(18, 2))' + CHAR(13) + CHAR(10) + N'    ) AS NormalValueMin' + CHAR(13) + CHAR(10) + N'FROM TransCharges AS tc' + CHAR(13) + CHAR(10) + N'INNER JOIN TransChargesItem AS tci  ' + CHAR(13) + CHAR(10) + N'    ON tci.TransactionNo = tc.TransactionNo' + CHAR(13) + CHAR(10) + N'LEFT JOIN Registration AS r' + CHAR(13) + CHAR(10) + N'    ON r.RegistrationNo = tc.RegistrationNo' + CHAR(13) + CHAR(10) + N'LEFT JOIN Patient AS p' + CHAR(13) + CHAR(10) + N'    ON p.PatientID = r.PatientID' + CHAR(13) + CHAR(10) + N'WHERE tc.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'  AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'')' + CHAR(13) + CHAR(10) + N'  AND (' + CHAR(13) + CHAR(10) + N'      (tci.IsOrderRealization = 1 AND tci.IsVoid = 0 AND tc.IsOrder = 1 AND tc.IsApproved = 1)' + CHAR(13) + CHAR(10) + N'      OR (tci.ParentNo IS NOT NULL AND LTRIM(RTRIM(tci.ParentNo)) <> '''')' + CHAR(13) + CHAR(10) + N'  )' + CHAR(13) + CHAR(10) + N'  AND tci.ResultValue IS NOT NULL AND LTRIM(RTRIM(tci.ResultValue)) <> ''''   ' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
