VALUES(0,N'10.1.2.02',1,N'LaboratoryProcedurePackageItemParent',1,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    ib.BridgingID,' + CHAR(13) + CHAR(10) + N'    ib.BridgingName' + CHAR(13) + CHAR(10) + N'FROM TransCharges AS tc' + CHAR(13) + CHAR(10) + N'INNER JOIN TransChargesItem AS parent' + CHAR(13) + CHAR(10) + N'    ON parent.TransactionNo = tc.TransactionNo' + CHAR(13) + CHAR(10) + N'OUTER APPLY (' + CHAR(13) + CHAR(10) + N'    SELECT TOP 1 ' + CHAR(13) + CHAR(10) + N'        ib.BridgingID,' + CHAR(13) + CHAR(10) + N'        ib.BridgingName' + CHAR(13) + CHAR(10) + N'    FROM ItemBridging AS ib' + CHAR(13) + CHAR(10) + N'    WHERE ib.ItemID = parent.ItemID AND ib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N') AS ib' + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    tc.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'    AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'')' + CHAR(13) + CHAR(10) + N'    AND (parent.ParentNo IS NULL OR LTRIM(RTRIM(parent.ParentNo)) = '''')' + CHAR(13) + CHAR(10) + N'    AND parent.IsOrderRealization = 1' + CHAR(13) + CHAR(10) + N'    AND parent.IsVoid = 0' + CHAR(13) + CHAR(10) + N'    AND parent.IsApprove = 1' + CHAR(13) + CHAR(10) + N'    AND parent.SRCollectMethod IS NOT NULL' + CHAR(13) + CHAR(10) + N'    AND LTRIM(RTRIM(parent.SRCollectMethod)) <> ''''' + CHAR(13) + CHAR(10) + N'    AND EXISTS (' + CHAR(13) + CHAR(10) + N'        SELECT 1' + CHAR(13) + CHAR(10) + N'        FROM TransChargesItem AS child' + CHAR(13) + CHAR(10) + N'        WHERE ' + CHAR(13) + CHAR(10) + N'            child.TransactionNo = parent.TransactionNo' + CHAR(13) + CHAR(10) + N'            AND LTRIM(RTRIM(child.ParentNo)) = CAST(parent.SequenceNo AS VARCHAR)' + CHAR(13) + CHAR(10) + N'            AND child.ResultValue IS NOT NULL' + CHAR(13) + CHAR(10) + N'            AND LTRIM(RTRIM(child.ResultValue)) <> ''''' + CHAR(13) + CHAR(10) + N'    )' + CHAR(13) + CHAR(10),1);
