VALUES(0,N'10.1.4.01',1,N'ItemLaboratoryUnitSingleItem',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN il.SRLaboratoryUnit IS NOT NULL' + CHAR(13) + CHAR(10) + N'            AND LEN(il.SRLaboratoryUnit) > 1' + CHAR(13) + CHAR(10) + N'            AND LEFT(il.SRLaboratoryUnit, 1) = ''×''' + CHAR(13) + CHAR(10) + N'        THEN LTRIM(SUBSTRING(il.SRLaboratoryUnit, 2, LEN(il.SRLaboratoryUnit) - 1))' + CHAR(13) + CHAR(10) + N'        ELSE il.SRLaboratoryUnit' + CHAR(13) + CHAR(10) + N'    END AS SRLaboratoryUnit' + CHAR(13) + CHAR(10) + N'FROM TransCharges AS tc' + CHAR(13) + CHAR(10) + N'INNER JOIN TransChargesItem AS tci' + CHAR(13) + CHAR(10) + N'    ON tc.TransactionNo = tci.TransactionNo' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemBridging AS ib' + CHAR(13) + CHAR(10) + N'    ON ib.ItemID = tci.ItemID' + CHAR(13) + CHAR(10) + N'    AND ib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemLaboratory AS il' + CHAR(13) + CHAR(10) + N'    ON tci.ItemID = il.ItemID' + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    tc.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'    AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'')' + CHAR(13) + CHAR(10) + N'    AND tci.IsOrderRealization = 1' + CHAR(13) + CHAR(10) + N'    AND tci.IsVoid = 0' + CHAR(13) + CHAR(10) + N'    AND tc.IsOrder = 1' + CHAR(13) + CHAR(10) + N'    AND tc.IsApproved = 1' + CHAR(13) + CHAR(10) + N'    AND tci.ResultValue IS NOT NULL' + CHAR(13) + CHAR(10) + N'    AND LTRIM(RTRIM(tci.ResultValue)) <> ''''' + CHAR(13) + CHAR(10) + N'    AND NOT EXISTS (' + CHAR(13) + CHAR(10) + N'        SELECT 1' + CHAR(13) + CHAR(10) + N'        FROM TransChargesItem AS child' + CHAR(13) + CHAR(10) + N'        WHERE ' + CHAR(13) + CHAR(10) + N'            child.TransactionNo = tci.TransactionNo' + CHAR(13) + CHAR(10) + N'            AND child.ParentNo = tci.SequenceNo' + CHAR(13) + CHAR(10) + N'    )' + CHAR(13) + CHAR(10) + N'    AND (tci.ParentNo IS NULL OR LTRIM(RTRIM(tci.ParentNo)) = '''')' + CHAR(13) + CHAR(10) + N'    AND tci.SRCollectMethod IS NOT NULL' + CHAR(13) + CHAR(10) + N'    AND LTRIM(RTRIM(tci.SRCollectMethod)) <> ''''' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'10.1.4.01',1,N'LaboratoryProcedureSingleItem',1,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    ib.BridgingID,' + CHAR(13) + CHAR(10) + N'    ib.BridgingName' + CHAR(13) + CHAR(10) + N'FROM TransCharges AS tc' + CHAR(13) + CHAR(10) + N'INNER JOIN TransChargesItem AS tci' + CHAR(13) + CHAR(10) + N'    ON tci.TransactionNo = tc.TransactionNo' + CHAR(13) + CHAR(10) + N'OUTER APPLY (' + CHAR(13) + CHAR(10) + N'    SELECT TOP 1 ' + CHAR(13) + CHAR(10) + N'        ib.BridgingID,' + CHAR(13) + CHAR(10) + N'        ib.BridgingName' + CHAR(13) + CHAR(10) + N'    FROM ItemBridging AS ib' + CHAR(13) + CHAR(10) + N'    WHERE ib.ItemID = tci.ItemID AND ib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N') AS ib' + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    tc.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'    AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'')' + CHAR(13) + CHAR(10) + N'    AND tci.IsOrderRealization = 1' + CHAR(13) + CHAR(10) + N'    AND tci.IsVoid = 0' + CHAR(13) + CHAR(10) + N'    AND tc.IsOrder = 1' + CHAR(13) + CHAR(10) + N'    AND tc.IsApproved = 1' + CHAR(13) + CHAR(10) + N'    AND tci.ResultValue IS NOT NULL' + CHAR(13) + CHAR(10) + N'    AND LTRIM(RTRIM(tci.ResultValue)) <> ''''' + CHAR(13) + CHAR(10) + N'    AND NOT EXISTS (' + CHAR(13) + CHAR(10) + N'        SELECT 1' + CHAR(13) + CHAR(10) + N'        FROM TransChargesItem AS child' + CHAR(13) + CHAR(10) + N'        WHERE ' + CHAR(13) + CHAR(10) + N'            child.TransactionNo = tci.TransactionNo' + CHAR(13) + CHAR(10) + N'            AND child.ParentNo = tci.SequenceNo' + CHAR(13) + CHAR(10) + N'    )' + CHAR(13) + CHAR(10) + N'    AND (' + CHAR(13) + CHAR(10) + N'        tci.ParentNo IS NULL' + CHAR(13) + CHAR(10) + N'        OR LTRIM(RTRIM(tci.ParentNo)) = ''''' + CHAR(13) + CHAR(10) + N'    )' + CHAR(13) + CHAR(10) + N'    AND tci.SRCollectMethod IS NOT NULL' + CHAR(13) + CHAR(10) + N'    AND LTRIM(RTRIM(tci.SRCollectMethod)) <> ''''' + CHAR(13) + CHAR(10),1);
