VALUES(0,N'10.1.4.02',1,N'LaboratoryTestValuePackageItem',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    tci.ResultValue' + CHAR(13) + CHAR(10) + N'FROM TransCharges AS tc' + CHAR(13) + CHAR(10) + N'INNER JOIN TransChargesItem AS tci' + CHAR(13) + CHAR(10) + N'    ON tci.TransactionNo = tc.TransactionNo' + CHAR(13) + CHAR(10) + N'INNER JOIN TransChargesItem AS parent' + CHAR(13) + CHAR(10) + N'    ON parent.TransactionNo = tci.TransactionNo' + CHAR(13) + CHAR(10) + N'   AND parent.SequenceNo = tci.ParentNo' + CHAR(13) + CHAR(10) + N'WHERE tc.RegistrationNo = ''@RegistrationNO''' + CHAR(13) + CHAR(10) + N'  AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'')' + CHAR(13) + CHAR(10) + N'  AND tci.ResultValue IS NOT NULL' + CHAR(13) + CHAR(10) + N'  AND LTRIM(RTRIM(tci.ResultValue)) <> ''''' + CHAR(13) + CHAR(10) + N'  AND tci.ParentNo IS NOT NULL' + CHAR(13) + CHAR(10) + N'  AND LTRIM(RTRIM(tci.ParentNo)) <> ''''' + CHAR(13) + CHAR(10) + N'  AND parent.SRCollectMethod IS NOT NULL' + CHAR(13) + CHAR(10) + N'  AND LTRIM(RTRIM(parent.SRCollectMethod)) <> ''''' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'10.1.4.02',1,N'LabTestInterpretationPackageItem',0,N'sql',N'SELECT' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN r.val < d.NormalValueMin THEN ''L''' + CHAR(13) + CHAR(10) + N'        WHEN r.val > d.NormalValueMax THEN ''H''' + CHAR(13) + CHAR(10) + N'        ELSE ''N''' + CHAR(13) + CHAR(10) + N'    END AS Code,' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN r.val < d.NormalValueMin THEN ''Low''' + CHAR(13) + CHAR(10) + N'        WHEN r.val > d.NormalValueMax THEN ''High''' + CHAR(13) + CHAR(10) + N'        ELSE ''Normal''' + CHAR(13) + CHAR(10) + N'    END AS Name' + CHAR(13) + CHAR(10) + N'FROM' + CHAR(13) + CHAR(10) + N'(' + CHAR(13) + CHAR(10) + N'    SELECT' + CHAR(13) + CHAR(10) + N'        i.ItemID AS ItemID,' + CHAR(13) + CHAR(10) + N'        tci.ResultValue AS val' + CHAR(13) + CHAR(10) + N'    FROM ' + CHAR(13) + CHAR(10) + N'        TransCharges AS tc' + CHAR(13) + CHAR(10) + N'        INNER JOIN TransChargesItem AS tci ' + CHAR(13) + CHAR(10) + N'            ON tci.TransactionNo = tc.TransactionNo' + CHAR(13) + CHAR(10) + N'        LEFT JOIN Item AS i ' + CHAR(13) + CHAR(10) + N'            ON i.ItemID = tci.ItemID' + CHAR(13) + CHAR(10) + N'    WHERE ' + CHAR(13) + CHAR(10) + N'        tc.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'        AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'')' + CHAR(13) + CHAR(10) + N'        AND tci.ResultValue IS NOT NULL' + CHAR(13) + CHAR(10) + N'        AND LTRIM(RTRIM(tci.ResultValue)) <> ''''' + CHAR(13) + CHAR(10) + N'        AND tci.ParentNo IS NOT NULL' + CHAR(13) + CHAR(10) + N'        AND LTRIM(RTRIM(tci.ParentNo)) <> ''''' + CHAR(13) + CHAR(10) + N'        AND EXISTS ' + CHAR(13) + CHAR(10) + N'        (' + CHAR(13) + CHAR(10) + N'            SELECT 1' + CHAR(13) + CHAR(10) + N'            FROM TransChargesItem AS parent' + CHAR(13) + CHAR(10) + N'            WHERE ' + CHAR(13) + CHAR(10) + N'                parent.TransactionNo = tci.TransactionNo' + CHAR(13) + CHAR(10) + N'                AND parent.SequenceNo = tci.ParentNo' + CHAR(13) + CHAR(10) + N'                AND parent.IsOrderRealization = 1' + CHAR(13) + CHAR(10) + N'                AND parent.IsVoid = 0' + CHAR(13) + CHAR(10) + N'                AND parent.IsApprove = 1' + CHAR(13) + CHAR(10) + N'                AND parent.SRCollectMethod IS NOT NULL' + CHAR(13) + CHAR(10) + N'                AND LTRIM(RTRIM(parent.SRCollectMethod)) <> ''''' + CHAR(13) + CHAR(10) + N'        )' + CHAR(13) + CHAR(10) + N') r' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemLaboratoryDetail AS d' + CHAR(13) + CHAR(10) + N'    ON d.ItemID = r.ItemID' + CHAR(13) + CHAR(10) + N'    AND d.Sex = (' + CHAR(13) + CHAR(10) + N'        SELECT Sex ' + CHAR(13) + CHAR(10) + N'        FROM Patient ' + CHAR(13) + CHAR(10) + N'        WHERE PatientID = ''{{PatientID_HIS}}''' + CHAR(13) + CHAR(10) + N'    )' + CHAR(13) + CHAR(10) + N'    AND DATEDIFF(' + CHAR(13) + CHAR(10) + N'        YEAR, ' + CHAR(13) + CHAR(10) + N'        (SELECT DateOfBirth FROM Patient WHERE PatientID = ''{{PatientID_HIS}}''),' + CHAR(13) + CHAR(10) + N'        GETDATE()' + CHAR(13) + CHAR(10) + N'    ) BETWEEN d.AgeMin AND d.AgeMax' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'10.1.4.02',1,N'LabTestNormalValueMaxPackageItem',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    ISNULL(' + CHAR(13) + CHAR(10) + N'        (' + CHAR(13) + CHAR(10) + N'            SELECT TOP 1 ' + CHAR(13) + CHAR(10) + N'                ild.NormalValueMax' + CHAR(13) + CHAR(10) + N'            FROM ' + CHAR(13) + CHAR(10) + N'                ItemLaboratoryDetail AS ild' + CHAR(13) + CHAR(10) + N'            WHERE ' + CHAR(13) + CHAR(10) + N'                ild.ItemID = tci.ItemID' + CHAR(13) + CHAR(10) + N'                AND ild.Sex = p.Sex' + CHAR(13) + CHAR(10) + N'                AND DATEDIFF(' + CHAR(13) + CHAR(10) + N'                    YEAR, ' + CHAR(13) + CHAR(10) + N'                    p.DateOfBirth, ' + CHAR(13) + CHAR(10) + N'                    GETDATE()' + CHAR(13) + CHAR(10) + N'                ) BETWEEN ild.AgeMin AND ild.AgeMax' + CHAR(13) + CHAR(10) + N'        ),' + CHAR(13) + CHAR(10) + N'        CAST(0 AS DECIMAL(18, 2))' + CHAR(13) + CHAR(10) + N'    ) AS NormalValueMin' + CHAR(13) + CHAR(10) + N'FROM ' + CHAR(13) + CHAR(10) + N'    TransCharges AS tc' + CHAR(13) + CHAR(10) + N'    INNER JOIN TransChargesItem AS tci ' + CHAR(13) + CHAR(10) + N'        ON tci.TransactionNo = tc.TransactionNo' + CHAR(13) + CHAR(10) + N'    LEFT JOIN Registration AS r ' + CHAR(13) + CHAR(10) + N'        ON r.RegistrationNo = tc.RegistrationNo' + CHAR(13) + CHAR(10) + N'    LEFT JOIN Patient AS p ' + CHAR(13) + CHAR(10) + N'        ON p.PatientID = r.PatientID' + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    tc.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'    AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'')' + CHAR(13) + CHAR(10) + N'    AND tci.ResultValue IS NOT NULL' + CHAR(13) + CHAR(10) + N'    AND LTRIM(RTRIM(tci.ResultValue)) <> ''''' + CHAR(13) + CHAR(10) + N'    AND tci.ParentNo IS NOT NULL' + CHAR(13) + CHAR(10) + N'    AND LTRIM(RTRIM(tci.ParentNo)) <> ''''' + CHAR(13) + CHAR(10) + N'    AND EXISTS (' + CHAR(13) + CHAR(10) + N'        SELECT 1' + CHAR(13) + CHAR(10) + N'        FROM TransChargesItem AS parent' + CHAR(13) + CHAR(10) + N'        WHERE ' + CHAR(13) + CHAR(10) + N'            parent.TransactionNo = tci.TransactionNo' + CHAR(13) + CHAR(10) + N'            AND parent.SequenceNo = tci.ParentNo' + CHAR(13) + CHAR(10) + N'            AND parent.IsOrderRealization = 1' + CHAR(13) + CHAR(10) + N'            AND parent.IsVoid = 0' + CHAR(13) + CHAR(10) + N'            AND parent.IsApprove = 1' + CHAR(13) + CHAR(10) + N'            AND parent.SRCollectMethod IS NOT NULL' + CHAR(13) + CHAR(10) + N'            AND LTRIM(RTRIM(parent.SRCollectMethod)) <> ''''' + CHAR(13) + CHAR(10) + N'    )' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'10.1.4.02',1,N'LabTestNormalValueMinPackageItem',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    ISNULL(' + CHAR(13) + CHAR(10) + N'        (' + CHAR(13) + CHAR(10) + N'            SELECT TOP 1 ' + CHAR(13) + CHAR(10) + N'                ild.NormalValueMin' + CHAR(13) + CHAR(10) + N'            FROM ' + CHAR(13) + CHAR(10) + N'                ItemLaboratoryDetail AS ild' + CHAR(13) + CHAR(10) + N'            WHERE ' + CHAR(13) + CHAR(10) + N'                ild.ItemID = tci.ItemID' + CHAR(13) + CHAR(10) + N'                AND ild.Sex = p.Sex' + CHAR(13) + CHAR(10) + N'                AND DATEDIFF(' + CHAR(13) + CHAR(10) + N'                    YEAR, ' + CHAR(13) + CHAR(10) + N'                    p.DateOfBirth, ' + CHAR(13) + CHAR(10) + N'                    GETDATE()' + CHAR(13) + CHAR(10) + N'                ) BETWEEN ild.AgeMin AND ild.AgeMax' + CHAR(13) + CHAR(10) + N'        ),' + CHAR(13) + CHAR(10) + N'        CAST(0 AS DECIMAL(18, 2))' + CHAR(13) + CHAR(10) + N'    ) AS NormalValueMin' + CHAR(13) + CHAR(10) + N'FROM ' + CHAR(13) + CHAR(10) + N'    TransCharges AS tc' + CHAR(13) + CHAR(10) + N'    INNER JOIN TransChargesItem AS tci ' + CHAR(13) + CHAR(10) + N'        ON tci.TransactionNo = tc.TransactionNo' + CHAR(13) + CHAR(10) + N'    LEFT JOIN Registration AS r ' + CHAR(13) + CHAR(10) + N'        ON r.RegistrationNo = tc.RegistrationNo' + CHAR(13) + CHAR(10) + N'    LEFT JOIN Patient AS p ' + CHAR(13) + CHAR(10) + N'        ON p.PatientID = r.PatientID' + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    tc.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'    AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'')' + CHAR(13) + CHAR(10) + N'    AND tci.ResultValue IS NOT NULL' + CHAR(13) + CHAR(10) + N'    AND LTRIM(RTRIM(tci.ResultValue)) <> ''''' + CHAR(13) + CHAR(10) + N'    AND tci.ParentNo IS NOT NULL' + CHAR(13) + CHAR(10) + N'    AND LTRIM(RTRIM(tci.ParentNo)) <> ''''' + CHAR(13) + CHAR(10) + N'    AND EXISTS (' + CHAR(13) + CHAR(10) + N'        SELECT 1' + CHAR(13) + CHAR(10) + N'        FROM TransChargesItem AS parent' + CHAR(13) + CHAR(10) + N'        WHERE ' + CHAR(13) + CHAR(10) + N'            parent.TransactionNo = tci.TransactionNo' + CHAR(13) + CHAR(10) + N'            AND parent.SequenceNo = tci.ParentNo' + CHAR(13) + CHAR(10) + N'            AND parent.IsOrderRealization = 1' + CHAR(13) + CHAR(10) + N'            AND parent.IsVoid = 0' + CHAR(13) + CHAR(10) + N'            AND parent.IsApprove = 1' + CHAR(13) + CHAR(10) + N'            AND parent.SRCollectMethod IS NOT NULL' + CHAR(13) + CHAR(10) + N'            AND LTRIM(RTRIM(parent.SRCollectMethod)) <> ''''' + CHAR(13) + CHAR(10) + N'    )' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'10.1.4.02',1,N'LabTransaction_DatePackageItem',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    tc.TransactionDate' + CHAR(13) + CHAR(10) + N'FROM TransCharges AS tc' + CHAR(13) + CHAR(10) + N'INNER JOIN TransChargesItem AS tci' + CHAR(13) + CHAR(10) + N'    ON tci.TransactionNo = tc.TransactionNo' + CHAR(13) + CHAR(10) + N'INNER JOIN TransChargesItem AS parent' + CHAR(13) + CHAR(10) + N'    ON parent.TransactionNo = tci.TransactionNo' + CHAR(13) + CHAR(10) + N'   AND parent.SequenceNo   = tci.ParentNo' + CHAR(13) + CHAR(10) + N'WHERE tc.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'  AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'')' + CHAR(13) + CHAR(10) + N'  AND tci.ResultValue IS NOT NULL' + CHAR(13) + CHAR(10) + N'  AND LTRIM(RTRIM(tci.ResultValue)) <> ''''' + CHAR(13) + CHAR(10) + N'  AND tci.ParentNo IS NOT NULL' + CHAR(13) + CHAR(10) + N'  AND LTRIM(RTRIM(tci.ParentNo)) <> ''''' + CHAR(13) + CHAR(10) + N'  AND parent.SRCollectMethod IS NOT NULL' + CHAR(13) + CHAR(10) + N'  AND parent.IsOrderRealization = 1 ' + CHAR(13) + CHAR(10) + N'  AND parent.IsVoid = 0 ' + CHAR(13) + CHAR(10) + N'  AND parent.IsApprove = 1' + CHAR(13) + CHAR(10) + N'  AND LTRIM(RTRIM(parent.SRCollectMethod)) <> ''''' + CHAR(13) + CHAR(10),1);
