VALUES(0,N'10.1.4.02',1,N'LabTransactionNoPackageItem',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    tci.TransactionNo + ''-'' + CAST(tci.SequenceNo AS VARCHAR) AS TransSeq' + CHAR(13) + CHAR(10) + N'FROM TransCharges AS tc' + CHAR(13) + CHAR(10) + N'INNER JOIN TransChargesItem AS tci' + CHAR(13) + CHAR(10) + N'    ON tci.TransactionNo = tc.TransactionNo' + CHAR(13) + CHAR(10) + N'WHERE tc.RegistrationNo  = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'  AND tc.ToServiceUnitID IN (''{{ServiceUnitLaboratoryID}}'')' + CHAR(13) + CHAR(10) + N'  AND tci.ParentNo IS NOT NULL' + CHAR(13) + CHAR(10) + N'  AND LTRIM(RTRIM(tci.ParentNo)) <> ''''' + CHAR(13) + CHAR(10) + N'  AND tci.ResultValue IS NOT NULL' + CHAR(13) + CHAR(10) + N'  AND LTRIM(RTRIM(tci.ResultValue)) <> ''''' + CHAR(13) + CHAR(10) + N'  AND EXISTS (' + CHAR(13) + CHAR(10) + N'        SELECT 1' + CHAR(13) + CHAR(10) + N'        FROM TransChargesItem parent' + CHAR(13) + CHAR(10) + N'        WHERE parent.TransactionNo = tci.TransactionNo' + CHAR(13) + CHAR(10) + N'          AND parent.SequenceNo = tci.ParentNo' + CHAR(13) + CHAR(10) + N'          AND parent.IsOrderRealization = 1 ' + CHAR(13) + CHAR(10) + CHAR(9) + CHAR(9) + N'  AND parent.IsVoid = 0 ' + CHAR(13) + CHAR(10) + CHAR(9) + CHAR(9) + N'  AND parent.IsApprove = 1' + CHAR(13) + CHAR(10) + N'    )' + CHAR(13) + CHAR(10),1);
