VALUES(0,N'10.2.2.01',1,N'DicomCode',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    asri.ItemID' + CHAR(13) + CHAR(10) + N'FROM TransCharges AS tc' + CHAR(13) + CHAR(10) + N'INNER JOIN TransChargesItem AS tci ' + CHAR(13) + CHAR(10) + N'    ON tci.TransactionNo = tc.TransactionNo' + CHAR(13) + CHAR(10) + N'INNER JOIN ItemRadiology AS ir' + CHAR(13) + CHAR(10) + CHAR(9) + N'ON ir.ItemID = tci.ItemID' + CHAR(13) + CHAR(10) + N'INNER JOIN AppStandardReferenceItem AS asri' + CHAR(13) + CHAR(10) + CHAR(9) + N'ON ir.DicomCode = asri.ItemID' + CHAR(13) + CHAR(10) + CHAR(9) + N'AND asri.StandardReferenceID = ''DicomCode''' + CHAR(13) + CHAR(10) + N'WHERE tc.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'  AND tc.ToServiceUnitID IN (''{{ServiceUnitRadiologyID}}'')' + CHAR(13) + CHAR(10) + N'  AND tci.IsOrderRealization = 1' + CHAR(13) + CHAR(10) + N'  AND tci.IsVoid = 0' + CHAR(13) + CHAR(10) + N'  AND tc.IsOrder = 1' + CHAR(13) + CHAR(10) + N'  AND tc.IsApproved = 1' + CHAR(13) + CHAR(10),1);
