VALUES(0,N'13.1',0,N'ProbabilityRisk',1,N'sql',N'SELECT TOP 1 ' + CHAR(13) + CHAR(10) + N'    CASE r.SRPatientRiskStatus' + CHAR(13) + CHAR(10) + N'        WHEN 0 THEN 0' + CHAR(13) + CHAR(10) + N'        WHEN 1 THEN 0.25' + CHAR(13) + CHAR(10) + N'        WHEN 2 THEN 0.50' + CHAR(13) + CHAR(10) + N'        WHEN 3 THEN 0.75' + CHAR(13) + CHAR(10) + N'        ELSE r.SRPatientRiskStatus' + CHAR(13) + CHAR(10) + N'    END AS RiskScore' + CHAR(13) + CHAR(10) + N'FROM Registration AS r' + CHAR(13) + CHAR(10) + N'INNER JOIN AppStandardReferenceItem AS asri' + CHAR(13) + CHAR(10) + N'    ON r.SRPatientRiskStatus = asri.ItemID' + CHAR(13) + CHAR(10) + N'WHERE r.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'  AND asri.StandardReferenceID = ''PatientRiskStatus''' + CHAR(13) + CHAR(10),0);
