VALUES(0,N'15.1.4.02',1,N'PrescriptionNoReview',0,N'sql',N'SELECT DISTINCT TOP 1 tpi.PrescriptionNo FROM TransPrescription AS tp   INNER JOIN TransPrescriptionItem AS tpi  ON tpi.PrescriptionNo = tp.PrescriptionNo  INNER JOIN PrescriptionReview AS pr  ON tp.PrescriptionNo = pr.PrescriptionNo  ' + CHAR(13) + CHAR(10) + N'WHERE tp.RegistrationNo = ''@RegistrationNo'' AND tp.IsVoid = 0 AND tpi.IsVoid = 0 AND tp.IsApproval = 1 AND tpi.IsApprove = 1 ',0);
