INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'15.1.4.02',1,N'PrescriptionReviewDate',0,N'sql',N'SELECT TOP 1 pr.LastUpdateDateTime' + CHAR(13) + CHAR(10) + N'FROM PrescriptionReview AS pr' + CHAR(13) + CHAR(10) + N'WHERE pr.PrescriptionNo IN (''{{PrescriptionNoReview}}'')',0);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'15.1.4.02',1,N'QuestionPrescription',0,N'sql',N'SELECT DISTINCT ' + CHAR(13) + CHAR(10) + N'    asrib.BridgingID,' + CHAR(13) + CHAR(10) + N'    asrib.BridgingName' + CHAR(13) + CHAR(10) + N'FROM PrescriptionReview AS pr' + CHAR(13) + CHAR(10) + N'INNER JOIN AppStandardReferenceItemBridging AS asrib' + CHAR(13) + CHAR(10) + N'    ON pr.SRPrescReview = asrib.ItemID' + CHAR(13) + CHAR(10) + N'    AND asrib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    pr.PrescriptionNo IN (''{{PrescriptionNoReview}}'')' + CHAR(13) + CHAR(10) + N'    AND asrib.StandardReferenceID = ''PrescReview''' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'15.1.4.02',1,N'ResponDataAllMedicationRequest',0,N'sql',N'SELECT' + CHAR(13) + CHAR(10) + N'    ''{ "resourceType": "Bundle", "type": "transaction-response", "entry": ['' +' + CHAR(13) + CHAR(10) + N'    STUFF((' + CHAR(13) + CHAR(10) + N'        SELECT '','' +' + CHAR(13) + CHAR(10) + N'            CASE' + CHAR(13) + CHAR(10) + N'                WHEN CHARINDEX(''['', RespondData) > 0' + CHAR(13) + CHAR(10) + N'                     AND CHARINDEX(''],"resourceType"'', RespondData) > CHARINDEX(''['', RespondData)' + CHAR(13) + CHAR(10) + N'                THEN SUBSTRING(' + CHAR(13) + CHAR(10) + N'                    RespondData,' + CHAR(13) + CHAR(10) + N'                    CHARINDEX(''['', RespondData) + 1,' + CHAR(13) + CHAR(10) + N'                    CHARINDEX(''],"resourceType"'', RespondData) - CHARINDEX(''['', RespondData) - 1' + CHAR(13) + CHAR(10) + N'                )' + CHAR(13) + CHAR(10) + N'                ELSE '''' ' + CHAR(13) + CHAR(10) + N'            END' + CHAR(13) + CHAR(10) + N'        FROM SatuSehatILPPreparation ssi' + CHAR(13) + CHAR(10) + N'        WHERE ssi.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'          AND ssi.TestNo IN (''15.1.1.02'',''15.1.4.01'')' + CHAR(13) + CHAR(10) + N'        FOR XML PATH(''''), TYPE).value(''.'', ''NVARCHAR(MAX)'')' + CHAR(13) + CHAR(10) + N'    , 1, 1, '''') +' + CHAR(13) + CHAR(10) + N'    ''], "total": '' +' + CHAR(13) + CHAR(10) + N'    CAST((' + CHAR(13) + CHAR(10) + N'        SELECT SUM(' + CHAR(13) + CHAR(10) + N'            (LEN(RespondData) - LEN(REPLACE(RespondData, ''{"response":'', '''')))' + CHAR(13) + CHAR(10) + N'            / NULLIF(LEN(''{"response":''), 0)' + CHAR(13) + CHAR(10) + N'        )' + CHAR(13) + CHAR(10) + N'        FROM SatuSehatILPPreparation ssi' + CHAR(13) + CHAR(10) + N'        WHERE ssi.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'          AND ssi.TestNo IN (''15.1.1.02'',''15.1.4.01'')' + CHAR(13) + CHAR(10) + N'    ) AS VARCHAR) +' + CHAR(13) + CHAR(10) + N'    '' }'' AS MergedJson' + CHAR(13) + CHAR(10) + CHAR(9),0);
