VALUES(0,N'15.2.01',1,N'DietPatient',1,N'sql',N'SELECT TOP 1 db.BridgingID, db.BridgingName FROM DietPatient AS dp INNER JOIN DietPatientItem AS dpi ON dp.TransactionNo = dpi.TransactionNo INNER JOIN diet AS d ON d.DietID = dpi.DietID INNER JOIN DietBridging AS db ON d.DietID = db.DietId WHERE  dp.RegistrationNo = ''@RegistrationNo'' AND db.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''  AND dp.IsVoid = 0    ',0);
