INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'18.1',1,N'ReferralType',1,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    asrib.BridgingID, ' + CHAR(13) + CHAR(10) + N'    asrib.BridgingName' + CHAR(13) + CHAR(10) + N'FROM ReferExternal AS re' + CHAR(13) + CHAR(10) + N'INNER JOIN AppStandardReferenceItem AS asri' + CHAR(13) + CHAR(10) + N'    ON asri.ItemID = re.SRReferType' + CHAR(13) + CHAR(10) + N'INNER JOIN AppStandardReferenceItemBridging AS asrib ' + CHAR(13) + CHAR(10) + N'    ON asrib.ItemID = re.SRReferType' + CHAR(13) + CHAR(10) + N'WHERE re.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'  AND asrib.StandardReferenceID = ''RefferalType''' + CHAR(13) + CHAR(10) + N'  AND asrib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'  AND asri.ItemID IN (''REFTYPE04'', ''REFTYPE05'')' + CHAR(13) + CHAR(10),0);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'18.2',0,N'AppointmentNoControlPlan',1,N'sql',N'SELECT TOP 1' + CHAR(13) + CHAR(10) + N'    JSON_VALUE(ControlPlan, ''$.Items[0].AppointmentNo'') AS AppointmentNo' + CHAR(13) + CHAR(10) + N'FROM MedicalDischargeSummaryByNurse' + CHAR(13) + CHAR(10) + N'WHERE RegistrationNo = ''@RegistrationNo''',0);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'18.2',0,N'ControlPlanDate',0,N'sql',N'SELECT TOP 1' + CHAR(13) + CHAR(10) + N'    JSON_VALUE(ControlPlan, ''$.Items[0].ControlPlanDateTime'') AS ControlPlanDateTime' + CHAR(13) + CHAR(10) + N'FROM MedicalDischargeSummaryByNurse' + CHAR(13) + CHAR(10) + N'WHERE RegistrationNo = ''@RegistrationNo''',0);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'18.2',0,N'ControlPlanNotes',0,N'sql',N'SELECT TOP 1' + CHAR(13) + CHAR(10) + N'    JSON_VALUE(ControlPlan, ''$.Items[0].Notes'') AS Notes' + CHAR(13) + CHAR(10) + N'FROM MedicalDischargeSummaryByNurse' + CHAR(13) + CHAR(10) + N'WHERE RegistrationNo = ''@RegistrationNo''',0);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'18.2',0,N'LocationControlPlan',0,N'sql',N'SELECT TOP 1' + CHAR(13) + CHAR(10) + N'    sb.BridgingID,' + CHAR(13) + CHAR(10) + N'    sb.BridgingName' + CHAR(13) + CHAR(10) + N'FROM MedicalDischargeSummaryByNurse m' + CHAR(13) + CHAR(10) + N'OUTER APPLY (' + CHAR(13) + CHAR(10) + N'    SELECT TOP 1 BridgingID, BridgingName' + CHAR(13) + CHAR(10) + N'    FROM ServiceUnitBridging sb' + CHAR(13) + CHAR(10) + N'    WHERE sb.ServiceUnitID = JSON_VALUE(m.ControlPlan, ''$.Items[0].ServiceUnitID'')' + CHAR(13) + CHAR(10) + N'    AND sb.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'    ORDER BY sb.BridgingID' + CHAR(13) + CHAR(10) + N') sb' + CHAR(13) + CHAR(10) + N'WHERE m.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10),0);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'18.2',0,N'PractitionerControlPlan',0,N'sql',N'SELECT TOP 1' + CHAR(13) + CHAR(10) + N'    pb.BridgingID,' + CHAR(13) + CHAR(10) + N'    pb.BridgingName' + CHAR(13) + CHAR(10) + N'FROM MedicalDischargeSummaryByNurse m' + CHAR(13) + CHAR(10) + N'OUTER APPLY (' + CHAR(13) + CHAR(10) + N'    SELECT TOP 1 BridgingID, BridgingName' + CHAR(13) + CHAR(10) + N'    FROM ParamedicBridging pb' + CHAR(13) + CHAR(10) + N'    WHERE pb.ParamedicID = JSON_VALUE(m.ControlPlan, ''$.Items[0].ParamedicID'')' + CHAR(13) + CHAR(10) + N'      AND pb.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'    ORDER BY pb.BridgingID' + CHAR(13) + CHAR(10) + N') pb' + CHAR(13) + CHAR(10) + N'WHERE m.RegistrationNo = ''@RegistrationNo''',0);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'20.1',1,N'DischargeDisposition',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN LOWER(asri.ReferenceId) IN (''faskes'', ''faskes lain'') ' + CHAR(13) + CHAR(10) + N'            THEN ''other-hcf'' ' + CHAR(13) + CHAR(10) + N'        ELSE ''home'' ' + CHAR(13) + CHAR(10) + N'    END AS Code,' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN LOWER(asri.ReferenceId) IN (''faskes'', ''faskes lain'') ' + CHAR(13) + CHAR(10) + N'            THEN ''Other healthcare facility''' + CHAR(13) + CHAR(10) + N'        ELSE ''Home''' + CHAR(13) + CHAR(10) + N'    END AS Display' + CHAR(13) + CHAR(10) + N'FROM Registration re' + CHAR(13) + CHAR(10) + N'LEFT JOIN ReferExternal rex ' + CHAR(13) + CHAR(10) + N'    ON re.RegistrationNo = rex.RegistrationNo' + CHAR(13) + CHAR(10) + N'LEFT JOIN Referral r ' + CHAR(13) + CHAR(10) + N'    ON rex.ReferralId = r.ReferralId' + CHAR(13) + CHAR(10) + N'LEFT JOIN AppStandardReferenceItem AS asri ' + CHAR(13) + CHAR(10) + N'    ON r.SrReferralGroup = asri.ItemId' + CHAR(13) + CHAR(10) + N'   AND asri.StandardReferenceID = ''Referralgroup''' + CHAR(13) + CHAR(10) + N'WHERE re.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10),0);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'20.1',1,N'InstructionFollowUp',0,N'sql',N'SELECT' + CHAR(13) + CHAR(10) + N'    CASE' + CHAR(13) + CHAR(10) + N'        WHEN mds.SuggestionFollowUp LIKE ''%<br%>%''' + CHAR(13) + CHAR(10) + N'            THEN ''Anjuran dokter untuk pulang dan kontrol kembali''' + CHAR(13) + CHAR(10) + N'        ELSE mds.SuggestionFollowUp' + CHAR(13) + CHAR(10) + N'    END AS SuggestionFollowUp' + CHAR(13) + CHAR(10) + N'FROM MedicalDischargeSummary AS mds' + CHAR(13) + CHAR(10) + N'WHERE mds.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10),0);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(0,N'21.1',1,N'EducationNotes',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    ISNULL(STRING_AGG(EducationNotes, ''. ''), '''') AS AllEducationNotes' + CHAR(13) + CHAR(10) + N'FROM PatientEducationLine' + CHAR(13) + CHAR(10) + N'WHERE RegistrationNo = ''@RegistrationNo''',0);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(100,N'-',1,N'DosageFormDispense',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    dosage_form_code,' + CHAR(13) + CHAR(10) + N'    dosage_form_name' + CHAR(13) + CHAR(10) + N'FROM (' + CHAR(13) + CHAR(10) + N'    SELECT ' + CHAR(13) + CHAR(10) + N'        tp.RegistrationNo,' + CHAR(13) + CHAR(10) + N'        JSON_VALUE(' + CHAR(13) + CHAR(10) + N'            CASE ' + CHAR(13) + CHAR(10) + N'                WHEN tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = '''' ' + CHAR(13) + CHAR(10) + N'                    THEN ssk1.ss_result' + CHAR(13) + CHAR(10) + N'                ELSE ssk2.ss_result' + CHAR(13) + CHAR(10) + N'            END,' + CHAR(13) + CHAR(10) + N'            ''$.data.dosage_form.code''' + CHAR(13) + CHAR(10) + N'        ) AS dosage_form_code,' + CHAR(13) + CHAR(10) + N'        JSON_VALUE(' + CHAR(13) + CHAR(10) + N'            CASE ' + CHAR(13) + CHAR(10) + N'                WHEN tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = '''' ' + CHAR(13) + CHAR(10) + N'                    THEN ssk1.ss_result' + CHAR(13) + CHAR(10) + N'                ELSE ssk2.ss_result' + CHAR(13) + CHAR(10) + N'            END,' + CHAR(13) + CHAR(10) + N'            ''$.data.dosage_form.name''' + CHAR(13) + CHAR(10) + N'        ) AS dosage_form_name,' + CHAR(13) + CHAR(10) + N'        tpi.ItemID AS item,' + CHAR(13) + CHAR(10) + N'        tpi.CreatedDateTime' + CHAR(13) + CHAR(10) + N'    FROM TransPrescription AS tp' + CHAR(13) + CHAR(10) + N'    INNER JOIN TransPrescriptionItem AS tpi' + CHAR(13) + CHAR(10) + N'        ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'    LEFT JOIN ItemBridging AS ib1' + CHAR(13) + CHAR(10) + N'        ON ib1.ItemID = tpi.ItemID' + CHAR(13) + CHAR(10) + N'        AND (tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = '''')' + CHAR(13) + CHAR(10) + N'        AND ib1.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'    LEFT JOIN ItemBridging AS ib2' + CHAR(13) + CHAR(10) + N'        ON ib2.ItemID = tpi.ItemInterventionID' + CHAR(13) + CHAR(10) + N'        AND (tpi.ItemInterventionID IS NOT NULL AND tpi.ItemInterventionID <> '''')' + CHAR(13) + CHAR(10) + N'        AND ib2.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'    LEFT JOIN SatuSehatKfa AS ssk1' + CHAR(13) + CHAR(10) + N'        ON ssk1.ss_uuid = ib1.BridgingID' + CHAR(13) + CHAR(10) + N'        AND (tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = '''')' + CHAR(13) + CHAR(10) + N'    LEFT JOIN SatuSehatKfa AS ssk2' + CHAR(13) + CHAR(10) + N'        ON ssk2.ss_uuid = ib2.BridgingID' + CHAR(13) + CHAR(10) + N'        AND (tpi.ItemInterventionID IS NOT NULL AND tpi.ItemInterventionID <> '''')' + CHAR(13) + CHAR(10) + N'    WHERE ' + CHAR(13) + CHAR(10) + N'        tp.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'        AND tp.IsVoid = 0' + CHAR(13) + CHAR(10) + N'        AND tpi.IsVoid = 0' + CHAR(13) + CHAR(10) + N'        AND tp.IsApproval = 1' + CHAR(13) + CHAR(10) + N'        AND tpi.IsApprove = 1' + CHAR(13) + CHAR(10) + N'        AND tpi.IsCompound = 0' + CHAR(13) + CHAR(10) + N'        AND tp.DeliverDateTime IS NOT NULL' + CHAR(13) + CHAR(10) + N') AS x' + CHAR(13) + CHAR(10) + N'ORDER BY ' + CHAR(13) + CHAR(10) + N'    x.CreatedDateTime' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(100,N'-',1,N'DrugDenominatorKfaDispense',0,N'sql',N'SELECT       1 AS denom,      asrib.BridgingID  FROM TransPrescription AS tp  INNER JOIN TransPrescriptionItem AS tpi     ' + CHAR(13) + CHAR(10) + N'ON tpi.PrescriptionNo = tp.PrescriptionNo  LEFT JOIN AppStandardReferenceItemBridging AS asrib      ON tpi.SRItemUnit = asrib.ItemID    ' + CHAR(13) + CHAR(10) + N'AND asrib.StandardReferenceID = ''ItemUnit''     AND asrib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''  ' + CHAR(13) + CHAR(10) + N'WHERE tp.RegistrationNo = ''@RegistrationNo''    AND tp.IsVoid = 0    AND tpi.IsVoid = 0    AND tp.IsApproval = 1   ' + CHAR(13) + CHAR(10) + N'AND tpi.IsApprove = 1    AND tpi.IsCompound = 0    AND tp.DeliverDateTime IS NOT NULL',1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(100,N'-',1,N'DrugDenominatorSystemKfaDispense',0,N'sql',N'SELECT       asrib.BridgingID,      CASE           WHEN asrib.BridgingID IN (''mg'', ''g'', ''mcg'', ''mL'', ''L'', ''IU'')             ' + CHAR(13) + CHAR(10) + N'THEN ''http://unitsofmeasure.org''          ELSE ''http://terminology.hl7.org/CodeSystem/v3-orderableDrugForm''      END AS denominator_system  ' + CHAR(13) + CHAR(10) + N'FROM TransPrescription AS tp  INNER JOIN TransPrescriptionItem AS tpi      ON tpi.PrescriptionNo = tp.PrescriptionNo  ' + CHAR(13) + CHAR(10) + N'LEFT JOIN AppStandardReferenceItemBridging AS asrib      ON tpi.SRItemUnit = asrib.ItemID     AND asrib.StandardReferenceID = ''ItemUnit''     ' + CHAR(13) + CHAR(10) + N'AND asrib.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''  WHERE tp.RegistrationNo = ''@RegistrationNo''    AND tp.IsVoid = 0    AND tpi.IsVoid = 0  ' + CHAR(13) + CHAR(10) + N'AND tp.IsApproval = 1    AND tpi.IsApprove = 1    AND tpi.IsCompound = 0 ' + CHAR(13) + CHAR(10) + N'AND tp.DeliverDateTime IS NOT NULL',1);
INSERT INTO [SatuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(100,N'-',1,N'DrugExpirationDateDispense',0,N'sql',N'SELECT ' + CHAR(10) + N'    CASE ' + CHAR(10) + N'        WHEN im.ExpiredDate IS NULL ' + CHAR(10) + N'        THEN CONVERT(DATE, DATEADD(DAY, 60, GETDATE()))' + CHAR(10) + N'        ELSE CONVERT(DATE, im.ExpiredDate)' + CHAR(10) + N'    END AS ExpiredDate' + CHAR(10) + CHAR(10) + N'FROM TransPrescription tp' + CHAR(10) + CHAR(10) + N'INNER JOIN TransPrescriptionItem tpi' + CHAR(10) + N'    ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(10) + CHAR(10) + N'CROSS APPLY (' + CHAR(10) + N'    SELECT TOP 1 *' + CHAR(10) + N'    FROM ItemMovement im' + CHAR(10) + N'    WHERE im.TransactionNo = tp.PrescriptionNo' + CHAR(10) + N'      AND im.SequenceNo = tpi.SequenceNo' + CHAR(10) + N'      AND im.TransactionCode = ''091''' + CHAR(10) + N'    ORDER BY im.MovementID DESC' + CHAR(10) + N') im' + CHAR(10) + CHAR(10) + N'WHERE tp.RegistrationNo = ''@RegistrationNo''' + CHAR(10) + N'  AND tp.IsVoid = 0' + CHAR(10) + N'  AND tpi.IsVoid = 0' + CHAR(10) + N'  AND tp.IsApproval = 1' + CHAR(10) + N'  AND tpi.IsApprove = 1' + CHAR(10) + N'  AND tpi.IsCompound = 0' + CHAR(10) + N'  AND tp.DeliverDateTime IS NOT NULL',1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(100,N'-',1,N'DrugIterationQtyDispense',0,N'sql',N'SELECT       ISNULL(cm.IterationQty, 1) AS IterationQty  FROM TransPrescription AS tp  INNER JOIN TransPrescriptionItem AS tpi     ' + CHAR(13) + CHAR(10) + N'ON tpi.PrescriptionNo = tp.PrescriptionNo  INNER JOIN ConsumeMethod AS cm      ON cm.SRConsumeMethod = tpi.SRConsumeMethod  ' + CHAR(13) + CHAR(10) + N'WHERE tp.RegistrationNo = ''@RegistrationNo''    AND tp.IsVoid = 0    AND tpi.IsVoid = 0    AND tp.IsApproval = 1    AND tpi.IsApprove = 1 ' + CHAR(13) + CHAR(10) + N'AND tpi.IsCompound = 0    AND tp.DeliverDateTime IS NOT NULL',1);
INSERT INTO [SatuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(100,N'-',1,N'DruglotNumberDispense',0,N'sql',N'SELECT ' + CHAR(10) + N'    CASE ' + CHAR(10) + N'        WHEN im.BatchNumber IS NULL OR LTRIM(RTRIM(im.BatchNumber)) = '''' THEN ''-''' + CHAR(10) + N'        ELSE im.BatchNumber' + CHAR(10) + N'    END AS BatchNumber' + CHAR(10) + N'FROM TransPrescription tp' + CHAR(10) + N'INNER JOIN TransPrescriptionItem tpi' + CHAR(10) + N'    ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(10) + CHAR(10) + N'CROSS APPLY (' + CHAR(10) + N'    SELECT TOP 1 *' + CHAR(10) + N'    FROM ItemMovement im' + CHAR(10) + N'    WHERE im.TransactionNo = tp.PrescriptionNo' + CHAR(10) + N'      AND im.SequenceNo = tpi.SequenceNo' + CHAR(10) + N'      AND im.TransactionCode = ''091''' + CHAR(10) + N'    ORDER BY im.MovementID DESC' + CHAR(10) + N') im' + CHAR(10) + CHAR(10) + N'WHERE tp.RegistrationNo = ''@RegistrationNo''' + CHAR(10) + N'  AND tp.IsVoid = 0' + CHAR(10) + N'  AND tpi.IsVoid = 0' + CHAR(10) + N'  AND tp.IsApproval = 1' + CHAR(10) + N'  AND tpi.IsApprove = 1' + CHAR(10) + N'  AND tpi.IsCompound = 0' + CHAR(10) + N'  AND tp.DeliverDateTime IS NOT NULL',1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(100,N'-',1,N'DrugNumeratorKfaDispense',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN CHARINDEX('' '', ai.kekuatan_zat_aktif + '' '') > 1' + CHAR(13) + CHAR(10) + N'            THEN LEFT(ai.kekuatan_zat_aktif, CHARINDEX('' '', ai.kekuatan_zat_aktif + '' '') - 1)' + CHAR(13) + CHAR(10) + N'        ELSE ai.kekuatan_zat_aktif' + CHAR(13) + CHAR(10) + N'    END AS kekuatan_value,' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN CHARINDEX('' '', ai.kekuatan_zat_aktif + '' '') < LEN(ai.kekuatan_zat_aktif) + 1' + CHAR(13) + CHAR(10) + N'            THEN LTRIM(' + CHAR(13) + CHAR(10) + N'                RIGHT(' + CHAR(13) + CHAR(10) + N'                    ai.kekuatan_zat_aktif,' + CHAR(13) + CHAR(10) + N'                    LEN(ai.kekuatan_zat_aktif) - CHARINDEX('' '', ai.kekuatan_zat_aktif + '' '')' + CHAR(13) + CHAR(10) + N'                )' + CHAR(13) + CHAR(10) + N'            )' + CHAR(13) + CHAR(10) + N'        ELSE NULL' + CHAR(13) + CHAR(10) + N'    END AS kekuatan_unit,' + CHAR(13) + CHAR(10) + N'    tpi.PrescriptionNo + ''-'' + CAST(tpi.SequenceNo AS VARCHAR) AS TransSeq' + CHAR(13) + CHAR(10) + N'FROM TransPrescription AS tp' + CHAR(13) + CHAR(10) + N'INNER JOIN TransPrescriptionItem AS tpi' + CHAR(13) + CHAR(10) + N'    ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemBridging AS ib1' + CHAR(13) + CHAR(10) + N'    ON ib1.ItemID = tpi.ItemID' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = '''')' + CHAR(13) + CHAR(10) + N'    AND ib1.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemBridging AS ib2' + CHAR(13) + CHAR(10) + N'    ON ib2.ItemID = tpi.ItemInterventionID' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NOT NULL AND tpi.ItemInterventionID <> '''')' + CHAR(13) + CHAR(10) + N'    AND ib2.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'LEFT JOIN SatuSehatKfa AS ssk1' + CHAR(13) + CHAR(10) + N'    ON ssk1.ss_uuid = ib1.BridgingID' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = '''')' + CHAR(13) + CHAR(10) + N'LEFT JOIN SatuSehatKfa AS ssk2' + CHAR(13) + CHAR(10) + N'    ON ssk2.ss_uuid = ib2.BridgingID' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NOT NULL AND tpi.ItemInterventionID <> '''')' + CHAR(13) + CHAR(10) + N'OUTER APPLY OPENJSON(' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = ''''' + CHAR(13) + CHAR(10) + N'            THEN ssk1.ss_result' + CHAR(13) + CHAR(10) + N'        ELSE ssk2.ss_result' + CHAR(13) + CHAR(10) + N'    END,' + CHAR(13) + CHAR(10) + N'    ''$.data.active_ingredients''' + CHAR(13) + CHAR(10) + N')' + CHAR(13) + CHAR(10) + N'WITH (' + CHAR(13) + CHAR(10) + N'    zat_aktif           NVARCHAR(200) ''$.zat_aktif'',' + CHAR(13) + CHAR(10) + N'    kekuatan_zat_aktif  NVARCHAR(200) ''$.kekuatan_zat_aktif'',' + CHAR(13) + CHAR(10) + N'    kfa_code            VARCHAR(20)   ''$.kfa_code''' + CHAR(13) + CHAR(10) + N') AS ai' + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    tp.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'    AND tp.IsVoid = 0' + CHAR(13) + CHAR(10) + N'    AND tpi.IsVoid = 0' + CHAR(13) + CHAR(10) + N'    AND tp.IsApproval = 1' + CHAR(13) + CHAR(10) + N'    AND tpi.IsApprove = 1' + CHAR(13) + CHAR(10) + N'    AND tpi.IsCompound = 0' + CHAR(13) + CHAR(10) + N'    AND tp.DeliverDateTime IS NOT NULL' + CHAR(13) + CHAR(10) + N'ORDER BY ' + CHAR(13) + CHAR(10) + N'    tpi.CreatedDateTime' + CHAR(13) + CHAR(10),1);
