VALUES(100,N'-',1,N'PatientDrugDispense',1,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    COALESCE(ib1.BridgingID, ib2.BridgingID) AS ItemID,' + CHAR(13) + CHAR(10) + N'    COALESCE(ib1.BridgingName, ib2.BridgingName) AS NamaItem' + CHAR(13) + CHAR(10) + N'FROM TransPrescription AS tp' + CHAR(13) + CHAR(10) + N'INNER JOIN TransPrescriptionItem AS tpi' + CHAR(13) + CHAR(10) + N'    ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemBridging AS ib1' + CHAR(13) + CHAR(10) + N'    ON ib1.ItemID = tpi.ItemID' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = '''')' + CHAR(13) + CHAR(10) + N'    AND ib1.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemBridging AS ib2' + CHAR(13) + CHAR(10) + N'    ON ib2.ItemID = tpi.ItemInterventionID' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NOT NULL AND tpi.ItemInterventionID <> '''')' + CHAR(13) + CHAR(10) + N'    AND ib2.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    tp.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'    AND tp.IsVoid = 0' + CHAR(13) + CHAR(10) + N'    AND tpi.IsVoid = 0' + CHAR(13) + CHAR(10) + N'    AND tp.IsApproval = 1' + CHAR(13) + CHAR(10) + N'    AND tpi.IsApprove = 1' + CHAR(13) + CHAR(10) + N'    AND tpi.IsCompound = 0' + CHAR(13) + CHAR(10) + N'    AND tp.DeliverDateTime IS NOT NULL           ' + CHAR(13) + CHAR(10),1);
