VALUES(100,N'-',1,N'PractitionerPrescDispense',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    COALESCE(pb1.BridgingID, pb2.BridgingID) AS BridgingID,' + CHAR(13) + CHAR(10) + N'    COALESCE(pb1.BridgingName, pb2.BridgingName) AS BridgingName' + CHAR(13) + CHAR(10) + N'FROM TransPrescription AS tp' + CHAR(13) + CHAR(10) + N'INNER JOIN TransPrescriptionItem AS tpi ' + CHAR(13) + CHAR(10) + N'    ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'LEFT JOIN AppUser AS au ' + CHAR(13) + CHAR(10) + N'    ON tp.DeliverByUserID = au.UserID' + CHAR(13) + CHAR(10) + N'LEFT JOIN ParamedicBridging AS pb1' + CHAR(13) + CHAR(10) + N'    ON au.ParamedicID = pb1.ParamedicID' + CHAR(13) + CHAR(10) + N'    AND pb1.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'LEFT JOIN ParamedicBridging AS pb2' + CHAR(13) + CHAR(10) + N'    ON tp.ParamedicID = pb2.ParamedicID' + CHAR(13) + CHAR(10) + N'    AND pb2.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'WHERE tp.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'  AND tp.IsVoid = 0' + CHAR(13) + CHAR(10) + N'  AND tpi.IsVoid = 0' + CHAR(13) + CHAR(10) + N'  AND tp.IsApproval = 1' + CHAR(13) + CHAR(10) + N'  AND tpi.IsApprove = 1' + CHAR(13) + CHAR(10) + N'  AND tpi.IsCompound = 0' + CHAR(13) + CHAR(10) + N'  AND tp.DeliverDateTime IS NOT NULL' + CHAR(13) + CHAR(10),1);
