INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(100,N'-',1,N'ResponDataMedicationRequestDispense',0,N'sql',N'SELECT JSON_QUERY(' + CHAR(13) + CHAR(10) + N'  (' + CHAR(13) + CHAR(10) + N'    SELECT' + CHAR(13) + CHAR(10) + N'      (' + CHAR(13) + CHAR(10) + N'        SELECT' + CHAR(13) + CHAR(10) + N'          JSON_QUERY([value], ''$.response'') AS [response]' + CHAR(13) + CHAR(10) + N'        FROM OPENJSON(' + CHAR(13) + CHAR(10) + N'              CASE ' + CHAR(13) + CHAR(10) + N'                WHEN ISJSON(ssi.RespondData) = 1 THEN ssi.RespondData ' + CHAR(13) + CHAR(10) + N'                ELSE ''{}''' + CHAR(13) + CHAR(10) + N'              END,' + CHAR(13) + CHAR(10) + N'              ''$.entry''' + CHAR(13) + CHAR(10) + N'            )' + CHAR(13) + CHAR(10) + N'        WHERE ISJSON([value]) = 1' + CHAR(13) + CHAR(10) + N'          AND [key] IN (' + CHAR(13) + CHAR(10) + N'            SELECT CAST(RowNum - 1 AS NVARCHAR(10))' + CHAR(13) + CHAR(10) + N'            FROM (' + CHAR(13) + CHAR(10) + N'              SELECT' + CHAR(13) + CHAR(10) + N'                ROW_NUMBER() OVER (ORDER BY tpi.PrescriptionNo) AS RowNum,' + CHAR(13) + CHAR(10) + N'                tp.DeliverDateTime' + CHAR(13) + CHAR(10) + N'              FROM TransPrescription AS tp' + CHAR(13) + CHAR(10) + N'              INNER JOIN TransPrescriptionItem AS tpi' + CHAR(13) + CHAR(10) + N'                ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'              WHERE tp.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'                AND tp.IsVoid = 0' + CHAR(13) + CHAR(10) + N'                AND tpi.IsVoid = 0' + CHAR(13) + CHAR(10) + N'                AND tp.IsApproval = 1' + CHAR(13) + CHAR(10) + N'                AND tpi.IsApprove = 1' + CHAR(13) + CHAR(10) + N'                AND tpi.IsCompound = 0' + CHAR(13) + CHAR(10) + N'            ) AS A' + CHAR(13) + CHAR(10) + N'            WHERE A.DeliverDateTime IS NOT NULL' + CHAR(13) + CHAR(10) + N'          )' + CHAR(13) + CHAR(10) + N'        FOR JSON PATH' + CHAR(13) + CHAR(10) + N'      ) AS entry,' + CHAR(13) + CHAR(10) + N'      (' + CHAR(13) + CHAR(10) + N'        SELECT COUNT(*)' + CHAR(13) + CHAR(10) + N'        FROM (' + CHAR(13) + CHAR(10) + N'          SELECT' + CHAR(13) + CHAR(10) + N'            ROW_NUMBER() OVER (ORDER BY tpi.PrescriptionNo) AS RowNum,' + CHAR(13) + CHAR(10) + N'            tp.DeliverDateTime' + CHAR(13) + CHAR(10) + N'          FROM TransPrescription AS tp' + CHAR(13) + CHAR(10) + N'          INNER JOIN TransPrescriptionItem AS tpi' + CHAR(13) + CHAR(10) + N'            ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'          WHERE tp.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'            AND tp.IsVoid = 0' + CHAR(13) + CHAR(10) + N'            AND tpi.IsVoid = 0' + CHAR(13) + CHAR(10) + N'            AND tp.IsApproval = 1' + CHAR(13) + CHAR(10) + N'            AND tpi.IsApprove = 1' + CHAR(13) + CHAR(10) + N'            AND tpi.IsCompound = 0' + CHAR(13) + CHAR(10) + N'        ) AS A' + CHAR(13) + CHAR(10) + N'        WHERE A.DeliverDateTime IS NOT NULL' + CHAR(13) + CHAR(10) + N'      ) AS total' + CHAR(13) + CHAR(10) + N'    FOR JSON PATH, WITHOUT_ARRAY_WRAPPER' + CHAR(13) + CHAR(10) + N'  )' + CHAR(13) + CHAR(10) + N')' + CHAR(13) + CHAR(10) + N'FROM SatuSehatILPPreparation AS ssi' + CHAR(13) + CHAR(10) + N'WHERE ssi.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'  AND ssi.TestNo = ''15.1.1.02''',0);
