VALUES(100,N'-',1,N'ServiceUnitPharmacyDispense',0,N'sql',N'SELECT       sub.BridgingID,      sub.BridgingName  FROM TransPrescription AS tp  INNER JOIN TransPrescriptionItem AS tpi      ON tpi.PrescriptionNo = tp.PrescriptionNo  LEFT JOIN ServiceUnitBridging AS sub  ON tp.ServiceUnitID = sub.ServiceUnitID   ' + CHAR(13) + CHAR(10) + N'WHERE tp.RegistrationNo = ''@RegistrationNo''    AND tp.IsVoid = 0    AND tpi.IsVoid = 0    AND tp.IsApproval = 1      AND tpi.IsApprove = 1    AND tpi.IsCompound = 0    AND tp.DeliverDateTime IS NOT NULL AND sub.SRBridgingType = ''{{SatuSehatBridgingTypeID}}'' ' + CHAR(13) + CHAR(10),1);
INSERT INTO [satuSehatILPTemplateDetailKeyWord]([TemplateID],[TestNo],[Sequence],[KeyWord],[IsQuestionAnswer],[SourceType],[Source],[IsMultipleAnswers])
VALUES(100,N'-',1,N'ZatAktifKfaDispense',0,N'sql',N'SELECT ' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = ''''' + CHAR(13) + CHAR(10) + N'            THEN ai1.kfa_code' + CHAR(13) + CHAR(10) + N'        ELSE ai2.kfa_code' + CHAR(13) + CHAR(10) + N'    END AS zat_aktif_code,' + CHAR(13) + CHAR(10) + N'    CASE ' + CHAR(13) + CHAR(10) + N'        WHEN tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = ''''' + CHAR(13) + CHAR(10) + N'            THEN ai1.zat_aktif' + CHAR(13) + CHAR(10) + N'        ELSE ai2.zat_aktif' + CHAR(13) + CHAR(10) + N'    END AS zat_aktif,' + CHAR(13) + CHAR(10) + N'    tpi.PrescriptionNo + ''-'' + CAST(tpi.SequenceNo AS VARCHAR) AS TransSeq' + CHAR(13) + CHAR(10) + N'FROM TransPrescription AS tp' + CHAR(13) + CHAR(10) + N'INNER JOIN TransPrescriptionItem AS tpi' + CHAR(13) + CHAR(10) + N'    ON tpi.PrescriptionNo = tp.PrescriptionNo' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemBridging AS ib1' + CHAR(13) + CHAR(10) + N'    ON ib1.ItemID = tpi.ItemID' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = '''')' + CHAR(13) + CHAR(10) + N'    AND ib1.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'LEFT JOIN ItemBridging AS ib2' + CHAR(13) + CHAR(10) + N'    ON ib2.ItemID = tpi.ItemInterventionID' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NOT NULL AND tpi.ItemInterventionID <> '''')' + CHAR(13) + CHAR(10) + N'    AND ib2.SRBridgingType = ''{{SatuSehatBridgingTypeID}}''' + CHAR(13) + CHAR(10) + N'LEFT JOIN SatuSehatKfa AS ssk1' + CHAR(13) + CHAR(10) + N'    ON ssk1.ss_uuid = ib1.BridgingID' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NULL OR tpi.ItemInterventionID = '''')' + CHAR(13) + CHAR(10) + N'LEFT JOIN SatuSehatKfa AS ssk2' + CHAR(13) + CHAR(10) + N'    ON ssk2.ss_uuid = ib2.BridgingID' + CHAR(13) + CHAR(10) + N'    AND (tpi.ItemInterventionID IS NOT NULL AND tpi.ItemInterventionID <> '''')' + CHAR(13) + CHAR(10) + N'OUTER APPLY OPENJSON(ssk1.ss_result, ''$.data.active_ingredients'')' + CHAR(13) + CHAR(10) + N'WITH (' + CHAR(13) + CHAR(10) + N'    kfa_code  VARCHAR(20)   ''$.kfa_code'',' + CHAR(13) + CHAR(10) + N'    zat_aktif NVARCHAR(200) ''$.zat_aktif''' + CHAR(13) + CHAR(10) + N') AS ai1' + CHAR(13) + CHAR(10) + N'OUTER APPLY OPENJSON(ssk2.ss_result, ''$.data.active_ingredients'')' + CHAR(13) + CHAR(10) + N'WITH (' + CHAR(13) + CHAR(10) + N'    kfa_code  VARCHAR(20)   ''$.kfa_code'',' + CHAR(13) + CHAR(10) + N'    zat_aktif NVARCHAR(200) ''$.zat_aktif''' + CHAR(13) + CHAR(10) + N') AS ai2' + CHAR(13) + CHAR(10) + N'WHERE ' + CHAR(13) + CHAR(10) + N'    tp.RegistrationNo = ''@RegistrationNo''' + CHAR(13) + CHAR(10) + N'    AND tp.IsVoid = 0' + CHAR(13) + CHAR(10) + N'    AND tpi.IsVoid = 0' + CHAR(13) + CHAR(10) + N'    AND tp.IsApproval = 1' + CHAR(13) + CHAR(10) + N'    AND tpi.IsApprove = 1' + CHAR(13) + CHAR(10) + N'    AND tpi.IsCompound = 0' + CHAR(13) + CHAR(10) + N'    AND tp.DeliverDateTime IS NOT NULL' + CHAR(13) + CHAR(10) + N'ORDER BY ' + CHAR(13) + CHAR(10) + N'    tpi.CreatedDateTime' + CHAR(13) + CHAR(10),1);
